/* View: QRY_SYSUSER10_SYSUSER11 */
CREATE OR ALTER VIEW QRY_SYSUSER10_SYSUSER11(
    RELA_SYSUSER10_INVITADO,
    RELA_SYSUSER10,
    ID_SYSUSER11,
    UUID_ANFITRION,
    SYSUSER10_NOMBRES,
    SYSUSER10_APELLIDOS,
    SYSUSER10_TELEFONO,
    SYSUSER10_CORREO,
    UUID_INVITADO,
    INVITADO_CORREO,
    SYSUSER11_STATUS,
    CON_CATALOGO,
    SYSUSER11_FAPL)
AS
select 
invitado.id_sysuser10,
anfitrion.id_sysuser10,
sysuser11_det_contactos.id_sysuser11,
anfitrion.sysuser10_uuid,
anfitrion.sysuser10_nombres,
anfitrion.sysuser10_apellidos,
anfitrion.sysuser10_telefono,
anfitrion.sysuser10_correo,
invitado.sysuser10_uuid,
invitado.sysuser10_correo,
iif(sysuser11_det_contactos.sysuser11_status = 0, 1, sysuser11_det_contactos.sysuser11_status),
iif(
    exists(
        select 1
        from sysuser41_det_productos p
        where p.rela_sysuser10 = anfitrion.id_sysuser10
          and p.sysuser41_status = 0
    ),
    1,
    0
) as con_catalogo,
sysuser11_det_contactos.sysuser11_fapl
from sysuser11_det_contactos
inner join sysuser10_cab_movil anfitrion on (sysuser11_det_contactos.rela_sysuser10_anfitrion = anfitrion.id_sysuser10)
inner join sysuser10_cab_movil invitado on (sysuser11_det_contactos.rela_sysuser10 = invitado.id_sysuser10)
;



/* View: QRY_SYSUSER40 */
CREATE OR ALTER VIEW QRY_SYSUSER40(
    RELA_SYSUSER11,
    RELA_SYSUSER10_ALTA,
    ID_SYSUSER40,
    SYSUSER40_CONCEPTO,
    SYSUSER40_CANTIDAD,
    SYSUSER40_IMPORTE,
    SYSUSER40_TOTAL,
    SYSUSER40_STATUS,
    SYSUSER40_FECHA,
    SYSUSER40_IMAGE,
    SYSUSER40_FAPL)
AS
select
sysuser40_det_compras.rela_sysuser11,
sysuser40_det_compras.rela_sysuser10_alta,
sysuser40_det_compras.id_sysuser40,
sysuser40_det_compras.sysuser40_concepto,
sysuser40_det_compras.sysuser40_cantidad,
sysuser40_det_compras.sysuser40_importe,
sysuser40_det_compras.sysuser40_cantidad * sysuser40_det_compras.sysuser40_importe,
sysuser40_det_compras.sysuser40_status,
sysuser40_det_compras.sysuser40_fecha,
(select first 1 sysjson02_tbl_files.sysjson02_alias || sysjson02_tbl_files.sysjson02_uuid
 from sysuser43_det_imagenes
 inner join sysjson02_tbl_files on (sysjson02_tbl_files.id_sysjson02 = sysuser43_det_imagenes.rela_sysjson02)
 where sysuser43_det_imagenes.rela_sysuser40 = sysuser40_det_compras.id_sysuser40
 order by sysuser43_det_imagenes.id_sysuser43 desc
),
sysuser40_det_compras.sysuser40_fapl
from sysuser40_det_compras
;



/* View: QRY_SYSUSER40_VS_SYSUSER50 */
CREATE OR ALTER VIEW QRY_SYSUSER40_VS_SYSUSER50(
    RELA_SYSUSER11,
    RELA_SYSUSER40,
    RELA_SYSUSER50,
    RELA_SYSUSER10_ALTA,
    ID_SYSUSER90,
    SYSUSER90_TIPO,
    SYSUSER90_CONCEPTO,
    SYSUSER90_CANTIDAD,
    SYSUSER90_IMPORTE,
    SYSUSER90_TOTAL,
    SYSUSER90_FECHA,
    SYSUSER90_STATUS,
    SYSUSER90_MOTIVO,
    SYSUSER90_FAPL)
AS
select
    x.rela_sysuser11,
    x.rela_sysuser40,
    x.rela_sysuser50,
    x.rela_sysuser10_alta,
    x.id_sysuser90,
    x.sysuser90_tipo,
    x.sysuser90_concepto,
    x.sysuser90_cantidad,
    x.sysuser90_importe,
    x.sysuser90_total,
    x.sysuser90_fecha,
    x.sysuser90_status,
    x.sysuser90_motivo,
    x.sysuser90_fapl
from (
    select
        c.rela_sysuser11,
        cast(c.id_sysuser40 as bigint) as rela_sysuser40,
        cast(null as bigint) as rela_sysuser50,
        c.rela_sysuser10_alta,
        c.id_sysuser40 as id_sysuser90,
        cast('Compra' as varchar(50)) as sysuser90_tipo,
        trim(c.sysuser40_concepto) as sysuser90_concepto,
        c.sysuser40_cantidad as sysuser90_cantidad,
        c.sysuser40_importe as sysuser90_importe,
        c.sysuser40_cantidad * c.sysuser40_importe as sysuser90_total,
        c.sysuser40_fecha as sysuser90_fecha,
        c.sysuser40_status as sysuser90_status,
        cast('' as varchar(8000)) as sysuser90_motivo,
        c.sysuser40_fapl as sysuser90_fapl
    from sysuser40_det_compras c

    union all

    select
        p.rela_sysuser11,
        cast(null as bigint) as rela_sysuser40,
        cast(p.id_sysuser50 as bigint) as rela_sysuser50,
        p.rela_sysuser10_alta,
        p.id_sysuser50 + 1000,
        cast('Pago' as varchar(50)) as sysuser90_tipo,
        trim(p.sysuser50_referencia) as sysuser90_concepto,
        cast(0 as double precision) as sysuser90_cantidad,
        p.sysuser50_importe * (-1) as sysuser90_importe,
        p.sysuser50_importe * (-1) as sysuser90_total,
        p.sysuser50_fecha as sysuser90_fecha,
        p.sysuser50_status as sysuser90_status,
        p.sysuser50_motivo as sysuser90_motivo,
        p.sysuser50_fapl
    from sysuser50_det_pagos p
) x
order by x.sysuser90_fapl desc, x.id_sysuser90 desc
;



/* View: QRY_SYSUSER41 */
CREATE OR ALTER VIEW QRY_SYSUSER41(
    RELA_SYSUSER10,
    ID_SYSUSER41,
    SYSUSER41_PRODUCTO,
    SYSUSER41_INVENTARIO,
    SYSUSER41_IMPORTE,
    SYSUSER41_STATUS,
    SYSUSER41_IMAGE,
    SYSUSER41_EXISTENCIA,
    SYSUSER41_FAPL)
AS
select
SYSUSER41_DET_PRODUCTOS.rela_sysuser10,
SYSUSER41_DET_PRODUCTOS.id_sysuser41,
SYSUSER41_DET_PRODUCTOS.sysuser41_producto,
SYSUSER41_DET_PRODUCTOS.sysuser41_inventario,
SYSUSER41_DET_PRODUCTOS.sysuser41_importe,
SYSUSER41_DET_PRODUCTOS.sysuser41_status,
(select first 1 sysjson02_tbl_files.sysjson02_alias || sysjson02_tbl_files.sysjson02_uuid
 from sysuser42_det_imagenes
 inner join sysjson02_tbl_files on (sysjson02_tbl_files.id_sysjson02 = sysuser42_det_imagenes.rela_sysjson02)
 where sysuser42_det_imagenes.rela_sysuser41 = SYSUSER41_DET_PRODUCTOS.id_sysuser41
 order by sysuser42_det_imagenes.id_sysuser42 desc
),
COALESCE((
    SELECT SUM(M.SYSUSER46_CANTIDAD)
    FROM SYSUSER46_MOV_INVENTARIO M
    WHERE M.RELA_SYSUSER41 =
          SYSUSER41_DET_PRODUCTOS.ID_SYSUSER41
), 0) AS SYSUSER41_EXISTENCIA,
SYSUSER41_DET_PRODUCTOS.sysuser41_fapl
from SYSUSER41_DET_PRODUCTOS
;



