/* Trigger: TID_SYSUSER40 */
CREATE OR ALTER TRIGGER TID_SYSUSER40 FOR SYSUSER40_DET_COMPRAS
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID BIGINT;

BEGIN 
    IF (INSERTING) THEN 
    BEGIN 
        NEW.ID_SYSUSER40 = GEN_ID(SID_SYSUSER40,1); 
        cTipo = 'A'; 
        nID = NEW.ID_SYSUSER40; 
    END 
    ELSE IF (UPDATING) THEN 
    BEGIN 
        cTipo = 'M'; 
        nID = OLD.ID_SYSUSER40; 

        if (old.SYSUSER40_STATUS <> 2
            and new.SYSUSER40_STATUS = 2
            and new.RELA_SYSUSER41 is not null) then
        begin
            insert into SYSUSER46_MOV_INVENTARIO (
                RELA_SYSUSER41,
                RELA_SYSUSER40,
                SYSUSER46_STATUS,
                SYSUSER46_CANTIDAD
            )
            values (
                NEW.RELA_SYSUSER41,
                NEW.ID_SYSUSER40,
                'C',
                NEW.SYSUSER40_CANTIDAD * -1
            );
        end
    END 
    ELSE 
    BEGIN 
        cTipo = 'B'; 
        nID = OLD.ID_SYSUSER40; 
    END 

    EXECUTE PROCEDURE smx$db_util_logs 
            CURRENT_USER, 
            :cTipo, 
            'SYSUSER40',
            :nID; 
END
^


