/* Trigger: TID_SYSUSER41_INVENTARIO */
CREATE OR ALTER TRIGGER TID_SYSUSER41_INVENTARIO FOR SYSUSER41_DET_PRODUCTOS
ACTIVE AFTER INSERT OR UPDATE POSITION 0
AS

DECLARE VARIABLE suma double precision;
DECLARE VARIABLE nID BIGINT; 

begin
    IF (INSERTING) THEN 
    BEGIN 
        nID = NEW.ID_SYSUSER41;
    END 
    ELSE IF (UPDATING) THEN 
    BEGIN 
        nID = OLD.ID_SYSUSER41;
    END 

    IF (
        INSERTING
        OR NEW.sysuser41_inventario IS DISTINCT FROM OLD.sysuser41_inventario
    ) THEN
    begin
        SELECT COALESCE(SUM(M.SYSUSER46_CANTIDAD), 0)
        FROM SYSUSER46_MOV_INVENTARIO M
        WHERE M.RELA_SYSUSER41 = :nID
        INTO :suma;

        /* Neutralizar existencia anterior */
        IF (suma <> 0) THEN
        BEGIN
            INSERT INTO SYSUSER46_MOV_INVENTARIO (
                RELA_SYSUSER41,
                SYSUSER46_STATUS,
                SYSUSER46_CANTIDAD
            )
            VALUES (
                :nID,
                'N',
                :suma * -1
            );
        END

        /* Registrar nueva existencia */
        IF (COALESCE(NEW.SYSUSER41_INVENTARIO, 0) > 0) THEN
        BEGIN
            INSERT INTO SYSUSER46_MOV_INVENTARIO (
                RELA_SYSUSER41,
                SYSUSER46_STATUS,
                SYSUSER46_CANTIDAD
            )
            VALUES (
                :nID,
                'I',
                NEW.SYSUSER41_INVENTARIO
            );
        END
    end
end
^


