CREATE OR ALTER TRIGGER TID_SYSUSER99 FOR SYSUSER99_DEP_SEGURIDAD
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID BIGINT; 
DECLARE VARIABLE V_USUARIO VARCHAR(50);
DECLARE VARIABLE V_SQL VARCHAR(1000);

BEGIN 
    IF (INSERTING) THEN 
    BEGIN 
        NEW.ID_SYSUSER99 = GEN_ID(SID_SYSUSER99,1); 
        cTipo = 'A'; 
        nID = NEW.ID_SYSUSER99; 
    END 
    ELSE IF (UPDATING) THEN 
    BEGIN 
        cTipo = 'M'; 
        nID = OLD.ID_SYSUSER99; 
    END 
    ELSE 
    BEGIN 
        cTipo = 'B'; 
        nID = OLD.ID_SYSUSER99; 

        V_USUARIO = 'JAM$_Z' || RIGHT('000000' || CAST(OLD.rela_sysuser10 AS VARCHAR(20)), 6);

        BEGIN
            V_SQL = 'DROP USER ' || V_USUARIO;
            EXECUTE STATEMENT :V_SQL
            AS USER 'SYSDBA' PASSWORD 'masterkey';
        WHEN ANY DO
            BEGIN
                /* No detenemos el DELETE si el usuario no existe
                   o si Firebird no permite borrarlo por alguna razon. */
            END
        END
    END 

    EXECUTE PROCEDURE smx$db_util_logs 
            CURRENT_USER, 
            :cTipo, 
            'SYSUSER99',
            :nID; 
END
^


SET TERM ; ^



