/***                           Stored Procedures                            ***/
/******************************************************************************/


SET TERM ^ ;

CREATE OR ALTER PROCEDURE ADD_SYSUSER10 (
    SYSUSER10_NOMBRES_P VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_CORREO_P VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_GEOLOC_ULT_P VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    RELA_SYSJSON02 BIGINT,
    ID_SYSUSER10 BIGINT,
    SYSUSER10_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_NOMBRES VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_APELLIDOS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_TELEFONO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_CORREO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_CORREO_01 VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_FECHA DATE,
    SYSUSER10_GEOLOC_ULT VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER99_USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER99_UUID_ANFITRION VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER99_PASSWORD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_FAPL TIMESTAMP)
AS
begin
    Select
    SYSUSER10_CAB_MOVIL.rela_sysjson02,
    SYSUSER10_CAB_MOVIL.id_sysuser10,
    SYSUSER10_CAB_MOVIL.sysuser10_uuid,
    SYSUSER10_CAB_MOVIL.sysuser10_nombres,
    SYSUSER10_CAB_MOVIL.sysuser10_apellidos,
    SYSUSER10_CAB_MOVIL.sysuser10_telefono,
    SYSUSER10_CAB_MOVIL.sysuser10_correo,
    SYSUSER10_CAB_MOVIL.sysuser10_correo_01,
    SYSUSER10_CAB_MOVIL.sysuser10_fecha,
    SYSUSER10_CAB_MOVIL.sysuser10_geoloc_ult,
    SYSUSER10_CAB_MOVIL.sysuser10_fapl
    from SYSUSER10_CAB_MOVIL
    where SYSUSER10_CORREO = :sysuser10_correo_p
    into :rela_sysjson02,
         :id_sysuser10,
         :sysuser10_uuid,
         :sysuser10_nombres,
         :sysuser10_apellidos,
         :sysuser10_telefono,
         :sysuser10_correo,
         :sysuser10_correo_01,
         :sysuser10_fecha,
         :sysuser10_geoloc_ult,
         :sysuser10_fapl;

    IF (id_sysuser10 IS NOT NULL) THEN
    BEGIN
        select
        SP_SYSUSER99_SEGURIDAD_GET.sysuser99_usuario,
        SP_SYSUSER99_SEGURIDAD_GET.sysuser99_password
        from SP_SYSUSER99_SEGURIDAD_GET(:id_sysuser10)
        into :sysuser99_usuario,
             :sysuser99_password;

        UPDATE SYSUSER11_DET_CONTACTOS
        SET SYSUSER11_STATUS_ACCION = 'I'
        WHERE RELA_SYSUSER10 = :ID_SYSUSER10
        AND SYSUSER11_STATUS_ACCION <> 'I';

        select anfitrion.sysuser10_uuid
        from sysuser11_det_contactos relacion
        inner join sysuser10_cab_movil anfitrion on (anfitrion.id_sysuser10 = relacion.rela_sysuser10_anfitrion)
        where relacion.rela_sysuser10 = :id_sysuser10
        into :sysuser99_uuid_anfitrion;

        SUSPEND;
        EXIT;
    END

    insert into SYSUSER10_CAB_MOVIL(SYSUSER10_CAB_MOVIL.sysuser10_uuid,
                                    SYSUSER10_CAB_MOVIL.sysuser10_nombres,
                                    SYSUSER10_CAB_MOVIL.sysuser10_apellidos,
                                    SYSUSER10_CAB_MOVIL.sysuser10_telefono,
                                    SYSUSER10_CAB_MOVIL.sysuser10_correo,
                                    SYSUSER10_CAB_MOVIL.sysuser10_correo_01,
                                    SYSUSER10_CAB_MOVIL.sysuser10_fecha,
                                    SYSUSER10_CAB_MOVIL.sysuser10_geoloc_ult)
    values(lower(UUID_TO_CHAR(GEN_UUID())),
           :sysuser10_nombres_p,
           '',
           '',
           :sysuser10_correo_p,
           :sysuser10_correo_p,
           current_date,
           :sysuser10_geoloc_ult_p)
    RETURNING rela_sysjson02,
              id_sysuser10,
              sysuser10_uuid,
              sysuser10_nombres,
              sysuser10_apellidos,
              sysuser10_telefono,
              sysuser10_correo,
              sysuser10_correo_01,
              sysuser10_fecha,
              sysuser10_geoloc_ult,
              sysuser10_fapl

    INTO :rela_sysjson02,
         :id_sysuser10,
         :sysuser10_uuid,
         :sysuser10_nombres,
         :sysuser10_apellidos,
         :sysuser10_telefono,
         :sysuser10_correo,
         :sysuser10_correo_01,
         :sysuser10_fecha,
         :sysuser10_geoloc_ult,
         :sysuser10_fapl;

    select
    SP_SYSUSER99_SEGURIDAD_GET.sysuser99_usuario,
    SP_SYSUSER99_SEGURIDAD_GET.sysuser99_password
    from SP_SYSUSER99_SEGURIDAD_GET(:id_sysuser10)
    into :sysuser99_usuario,
         :sysuser99_password;

    suspend;
end^


CREATE OR ALTER PROCEDURE ADD_SYSUSER10_SYSUSER11 (
    UUID_ANFITRION_P VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CORREO_INVITADO_P VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    MENSAJE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SYSUSER10 BIGINT,
    ID_SYSUSER11 BIGINT,
    SYSUSER10_NOMBRES VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_APELLIDOS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_TELEFONO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_CORREO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER11_STATUS INTEGER,
    CON_CATALOGO INTEGER,
    SYSUSER11_FAPL TIMESTAMP)
AS
declare variable V_ID_ANFITRION bigint;
declare variable V_ID_INVITADO bigint;
declare variable V_ID_RELACION bigint;
declare variable V_ID_ANFITRION_RELACION bigint;
declare variable V_STATUS_RELACION integer;
declare variable V_STATUS_ACCION varchar(1);
declare variable V_GENERA_CICLO integer;
BEGIN
    uuid_anfitrion_p = trim(lower(uuid_anfitrion_p));
    correo_invitado_p = trim(lower(correo_invitado_p));

    MENSAJE = '';
    RELA_SYSUSER10 = 0;
    ID_SYSUSER11 = 0;
    SYSUSER10_NOMBRES = '';
    SYSUSER10_APELLIDOS = '';
    SYSUSER10_TELEFONO = '';
    SYSUSER10_CORREO = '';
    SYSUSER11_STATUS = -1;
    CON_CATALOGO = 0;
    SYSUSER11_FAPL = CURRENT_TIMESTAMP;

    V_ID_ANFITRION = NULL;
    V_ID_INVITADO = NULL;
    V_ID_RELACION = NULL;
    V_ID_ANFITRION_RELACION = NULL;
    V_STATUS_RELACION = NULL;
    V_STATUS_ACCION = NULL;
    V_GENERA_CICLO = 0;

    /* Localiza al anfitrión mediante el UUID de la invitación. */
    SELECT FIRST 1
        U.ID_SYSUSER10
    FROM SYSUSER10_CAB_MOVIL U
    WHERE U.SYSUSER10_UUID = :UUID_ANFITRION_P
    INTO :V_ID_ANFITRION;

    IF (V_ID_ANFITRION IS NULL) THEN
    BEGIN
        MENSAJE =
            'No pudimos identificar al anfitrión de esta invitación. ' ||
            'Solicita un enlace nuevo.';

        SUSPEND;
        EXIT;
    END

    /* El invitado ya fue recuperado o creado durante el logon. */
    SELECT FIRST 1
        U.ID_SYSUSER10
    FROM SYSUSER10_CAB_MOVIL U
    WHERE TRIM(UPPER(U.SYSUSER10_CORREO)) =
          TRIM(UPPER(:CORREO_INVITADO_P))
    INTO :V_ID_INVITADO;

    IF (V_ID_INVITADO IS NULL) THEN
    BEGIN
        MENSAJE =
            'No pudimos identificar tu cuenta en SaldiFY. ' ||
            'Vuelve a iniciar sesión.';

        SUSPEND;
        EXIT;
    END

    /* Un anfitrión no puede utilizar su propia invitación. */
    IF (V_ID_ANFITRION = V_ID_INVITADO) THEN
    BEGIN
        MENSAJE =
            'No puedes utilizar tu propia invitación para ingresar ' ||
            'como cliente.';

        SUSPEND;
        EXIT;
    END

    /*
     * Recupera la relación existente del invitado, si la tiene,
     * junto con su anfitrión, estado y responsable de los datos.
     */
    SELECT FIRST 1
        C.ID_SYSUSER11,
        C.RELA_SYSUSER10_ANFITRION,
        C.SYSUSER11_STATUS,
        C.SYSUSER11_STATUS_ACCION
    FROM SYSUSER11_DET_CONTACTOS C
    WHERE C.RELA_SYSUSER10 = :V_ID_INVITADO
    ORDER BY C.ID_SYSUSER11 DESC
    INTO
        :V_ID_RELACION,
        :V_ID_ANFITRION_RELACION,
        :V_STATUS_RELACION,
        :V_STATUS_ACCION;

    /* Una invitación normal nunca traslada clientes entre anfitriones. */
    IF (
        V_ID_RELACION IS NOT NULL
        AND V_ID_ANFITRION_RELACION <> V_ID_ANFITRION
    ) THEN
    BEGIN
        MENSAJE =
            'Tu cuenta ya pertenece a otra red de SaldiFY. ' ||
            'No puedes aceptar esta invitación con la misma cuenta.';

        SUSPEND;
        EXIT;
    END

    /*
     * Si ya pertenece al mismo anfitrión, consolida la relación.
     * Una relación archivada no se reactiva automáticamente.
     */
    IF (V_ID_RELACION IS NOT NULL) THEN
    BEGIN
        IF (V_STATUS_RELACION = 0 OR V_STATUS_RELACION = 1) THEN
        BEGIN
            IF (
                V_STATUS_RELACION <> 1
                OR COALESCE(V_STATUS_ACCION, '') <> 'I'
            ) THEN
            BEGIN
                UPDATE SYSUSER11_DET_CONTACTOS
                SET SYSUSER11_STATUS = 1,
                    SYSUSER11_STATUS_ACCION = 'I'
                WHERE ID_SYSUSER11 = :V_ID_RELACION;
            END

            V_STATUS_RELACION = 1;
            V_STATUS_ACCION = 'I';
        END
        ELSE IF (V_STATUS_RELACION <> 2) THEN
        BEGIN
            MENSAJE =
                'La relación de esta invitación tiene un estado inválido. ' ||
                'Contacta al anfitrión.';

            SUSPEND;
            EXIT;
        END
    END

    /*
     * Si todavía no tiene anfitrión, verifica que el invitado no sea
     * ancestro del anfitrión que envió la invitación.
     */
    IF (V_ID_RELACION IS NULL) THEN
    BEGIN
        V_GENERA_CICLO = 0;

        WITH RECURSIVE ASCENDENCIA (
            RELA_SYSUSER10,
            RELA_SYSUSER10_ANFITRION
        ) AS (
            SELECT
                C.RELA_SYSUSER10,
                C.RELA_SYSUSER10_ANFITRION
            FROM SYSUSER11_DET_CONTACTOS C
            WHERE C.RELA_SYSUSER10 = :V_ID_ANFITRION

            UNION ALL

            SELECT
                C.RELA_SYSUSER10,
                C.RELA_SYSUSER10_ANFITRION
            FROM SYSUSER11_DET_CONTACTOS C
            INNER JOIN ASCENDENCIA A
                ON C.RELA_SYSUSER10 =
                   A.RELA_SYSUSER10_ANFITRION
        )
        SELECT FIRST 1
            1
        FROM ASCENDENCIA A
        WHERE A.RELA_SYSUSER10_ANFITRION = :V_ID_INVITADO
        INTO :V_GENERA_CICLO;

        IF (V_GENERA_CICLO = 1) THEN
        BEGIN
            MENSAJE =
                'No puedes aceptar esta invitación porque generaría ' ||
                'un ciclo dentro de la red de SaldiFY.';

            SUSPEND;
            EXIT;
        END
    END

    /* Crea la relación cuando el invitado todavía no tiene anfitrión. */
    IF (V_ID_RELACION IS NULL) THEN
    BEGIN
        INSERT INTO SYSUSER11_DET_CONTACTOS (
            RELA_SYSUSER10,
            RELA_SYSUSER10_ANFITRION,
            SYSUSER11_STATUS,
            SYSUSER11_STATUS_ACCION)
        VALUES (
            :V_ID_INVITADO,
            :V_ID_ANFITRION,
            1,
            'I')
        RETURNING ID_SYSUSER11
        INTO :V_ID_RELACION;

        V_STATUS_RELACION = 1;
        V_STATUS_ACCION = 'I';
    END

    /* Recupera la información consumida por Flutter. */
    SELECT
        Q.RELA_SYSUSER10,
        Q.ID_SYSUSER11,
        Q.SYSUSER10_NOMBRES,
        Q.SYSUSER10_APELLIDOS,
        Q.SYSUSER10_TELEFONO,
        Q.SYSUSER10_CORREO,
        Q.SYSUSER11_STATUS,
        Q.CON_CATALOGO,
        Q.SYSUSER11_FAPL
    FROM QRY_SYSUSER10_SYSUSER11 Q
    WHERE Q.ID_SYSUSER11 = :V_ID_RELACION
    INTO
        :RELA_SYSUSER10,
        :ID_SYSUSER11,
        :SYSUSER10_NOMBRES,
        :SYSUSER10_APELLIDOS,
        :SYSUSER10_TELEFONO,
        :SYSUSER10_CORREO,
        :SYSUSER11_STATUS,
        :CON_CATALOGO,
        :SYSUSER11_FAPL;

    IF (ROW_COUNT = 0) THEN
    BEGIN
        MENSAJE =
            'No pudimos recuperar la información de tu relación. ' ||
            'Intenta ingresar nuevamente.';

        SUSPEND;
        EXIT;
    END

    IF (V_STATUS_RELACION = 2) THEN
    BEGIN
        MENSAJE =
            'Tu relación fue archivada por el anfitrión. ' ||
            'Solicita su reactivación para volver a ingresar.';
    END
    ELSE
    BEGIN
        MENSAJE = 'OK';
    END

    SUSPEND;
END^


CREATE OR ALTER PROCEDURE ADD_SYSUSER41 (
    RELA_SYSUSER10 BIGINT,
    PRODUCTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION,
    INVENTARIO DOUBLE PRECISION)
RETURNS (
    ID_SYSUSER41 BIGINT,
    SYSUSER41_STATUS VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER41_FAPL TIMESTAMP)
AS
begin
  sysuser41_status = 'OK';
  sysuser41_fapl = current_timestamp;

  insert into sysuser41_det_productos(sysuser41_det_productos.rela_sysuser10,
                                      sysuser41_det_productos.sysuser41_producto,
                                      sysuser41_det_productos.sysuser41_importe,
                                      sysuser41_det_productos.sysuser41_inventario,
                                      sysuser41_det_productos.sysuser41_status)
  values(:rela_sysuser10, :producto, :importe, :inventario, 0) RETURNING ID_SYSUSER41 INTO :ID_SYSUSER41;

  suspend;
end^


CREATE OR ALTER PROCEDURE ADD_SYSUSER90_SALDIFY (
    CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UUID_ANFITRION VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_TMPUSER99 BIGINT,
    TMPUSER99_STATUS VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPUSER99_FAPL TIMESTAMP)
AS
declare variable ID_SYSUSER90 bigint;
begin
    id_tmpuser99 = 1;
    tmpuser99_status = 'DUPLICADO';
    tmpuser99_fapl = current_timestamp;
    uuid_anfitrion = trim(lower(uuid_anfitrion));

    select sysuser90_tbl_saldify.id_sysuser90
    from sysuser90_tbl_saldify
    where sysuser90_tbl_saldify.sysuser90_codigo = :codigo
    into :id_sysuser90;

    if (id_sysuser90 is null) then
    begin
        insert into sysuser90_tbl_saldify(sysuser90_tbl_saldify.sysuser90_codigo,
                                          sysuser90_tbl_saldify.sysuser90_anfitrion_uuid)
        values(:codigo,
               :uuid_anfitrion);

        tmpuser99_status = 'OK';
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE QRY_SYSUSER10_FIND (
    ID_SYSUSER10_ANFITRION BIGINT,
    CORREO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SYSUSER10 BIGINT,
    SYSUSER10_STATUS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_FAPL TIMESTAMP)
AS
DECLARE VARIABLE V_ID_SYSUSER11 BIGINT;
DECLARE VARIABLE V_SYSUSER11_STATUS INTEGER;
BEGIN
    ID_SYSUSER10 = NULL;
    SYSUSER10_STATUS = NULL;
    SYSUSER10_FAPL = NULL;

    V_ID_SYSUSER11 = NULL;
    V_SYSUSER11_STATUS = NULL;

    /*
     * Primero comprueba si el correo ya existe en SYSUSER10.
     * Si no existe, el procedimiento no devuelve ninguna fila.
     */
    SELECT FIRST 1
        U.ID_SYSUSER10,
        U.SYSUSER10_FAPL
    FROM SYSUSER10_CAB_MOVIL U
    WHERE TRIM(UPPER(U.SYSUSER10_CORREO)) =
          TRIM(UPPER(:CORREO))
    INTO
        :ID_SYSUSER10,
        :SYSUSER10_FAPL;

    IF (ID_SYSUSER10 IS NULL) THEN
        EXIT;

    /*
     * El correo existe. Este es el mensaje predeterminado cuando
     * el usuario no tiene una relación directa con el anfitrión.
     */
    SYSUSER10_STATUS =
        'Este correo ya está registrado en SaldiFY y no puede darse de alta manualmente.';

    /*
     * Comprueba únicamente si ya pertenece directamente a la red
     * del anfitrión que está realizando el alta.
     */
    SELECT FIRST 1
        C.ID_SYSUSER11,
        C.SYSUSER11_STATUS
    FROM SYSUSER11_DET_CONTACTOS C
    WHERE C.RELA_SYSUSER10 = :ID_SYSUSER10
      AND C.RELA_SYSUSER10_ANFITRION = :ID_SYSUSER10_ANFITRION
    ORDER BY C.ID_SYSUSER11 DESC
    INTO
        :V_ID_SYSUSER11,
        :V_SYSUSER11_STATUS;

    IF (V_ID_SYSUSER11 IS NOT NULL) THEN
    BEGIN
        IF (V_SYSUSER11_STATUS = 0) THEN
            SYSUSER10_STATUS =
                'Este usuario ya se encuentra en Clientes pendientes.';
        ELSE IF (V_SYSUSER11_STATUS = 1) THEN
            SYSUSER10_STATUS =
                'Este usuario ya forma parte de tus clientes.';
        ELSE IF (V_SYSUSER11_STATUS = 2) THEN
            SYSUSER10_STATUS =
                'Este usuario se encuentra en Clientes archivados.';
        ELSE
            SYSUSER10_STATUS =
                'Este usuario ya se encuentra vinculado a tu red.';
    END

    SUSPEND;
END^


CREATE OR ALTER PROCEDURE QRY_SYSUSER10_HISTORIAL (
    RELA_SYSUSER10 BIGINT,
    RELA_SYSUSER10_ANFITRION BIGINT)
RETURNS (
    RELA_SYSUSER40 INTEGER,
    RELA_SYSUSER50 INTEGER,
    ID_SYSUSER90 INTEGER,
    SYSUSER90_TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER90_CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER90_CANTIDAD DOUBLE PRECISION,
    SYSUSER90_IMPORTE DOUBLE PRECISION,
    SYSUSER90_TOTAL DOUBLE PRECISION,
    SYSUSER90_FECHA DATE,
    SYSUSER90_STATUS INTEGER,
    SYSUSER90_OWNER VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER90_MOTIVO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER90_FAPL TIMESTAMP)
AS
declare variable ID_SYSUSER11 bigint;
declare variable RELA_SYSUSER10_ALTA bigint;
begin
    select sysuser11_det_contactos.id_sysuser11
    from sysuser11_det_contactos
    where sysuser11_det_contactos.rela_sysuser10 = :rela_sysuser10
    and sysuser11_det_contactos.rela_sysuser10_anfitrion = :rela_sysuser10_anfitrion
    into :id_sysuser11;
    
    for select
    qry_sysuser40_vs_sysuser50.rela_sysuser40,
    qry_sysuser40_vs_sysuser50.rela_sysuser50,
    qry_sysuser40_vs_sysuser50.rela_sysuser10_alta,
    qry_sysuser40_vs_sysuser50.id_sysuser90,
    qry_sysuser40_vs_sysuser50.sysuser90_tipo,
    qry_sysuser40_vs_sysuser50.sysuser90_concepto,
    qry_sysuser40_vs_sysuser50.sysuser90_cantidad,
    qry_sysuser40_vs_sysuser50.sysuser90_importe,
    qry_sysuser40_vs_sysuser50.sysuser90_total,
    qry_sysuser40_vs_sysuser50.sysuser90_fecha,
    qry_sysuser40_vs_sysuser50.sysuser90_status,
    qry_sysuser40_vs_sysuser50.sysuser90_motivo,
    qry_sysuser40_vs_sysuser50.sysuser90_fapl
    from qry_sysuser40_vs_sysuser50
    where qry_sysuser40_vs_sysuser50.rela_sysuser11 = :id_sysuser11
    into :rela_sysuser40,
         :rela_sysuser50,
         :rela_sysuser10_alta,
         :id_sysuser90,
         :sysuser90_tipo,
         :sysuser90_concepto,
         :sysuser90_cantidad,
         :sysuser90_importe,
         :sysuser90_total,
         :sysuser90_fecha,
         :sysuser90_status,
         :sysuser90_motivo,
         :sysuser90_fapl
    do
    begin
        if (rela_sysuser10_alta = rela_sysuser10_anfitrion) then
            sysuser90_owner = 'Empresa';
        else
            sysuser90_owner = 'Cliente';
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE QRY_SYSUSER10_HISTORIAL_REP (
    RELA_SYSUSER10_ANFITRION BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE,
    TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SYSUSER90 INTEGER,
    SYSUSER90_ENTIDAD VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER90_CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER90_CANTIDAD DOUBLE PRECISION,
    SYSUSER90_IMPORTE DOUBLE PRECISION,
    SYSUSER90_TOTAL DOUBLE PRECISION,
    SYSUSER90_FECHA DATE,
    SYSUSER90_STATUS INTEGER,
    SYSUSER90_OWNER VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER90_MOTIVO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER90_FAPL TIMESTAMP)
AS
declare variable RELA_SYSUSER10_ALTA bigint;
declare variable SYSUSER10_NOMBRES varchar(400);
declare variable SYSUSER10_APELLIDOS varchar(400);
begin
    for select
    qry_sysuser40_vs_sysuser50.rela_sysuser10_alta,
    qry_sysuser40_vs_sysuser50.id_sysuser90,
    qry_sysuser40_vs_sysuser50.sysuser90_concepto,
    qry_sysuser40_vs_sysuser50.sysuser90_cantidad,
    qry_sysuser40_vs_sysuser50.sysuser90_importe,
    qry_sysuser40_vs_sysuser50.sysuser90_total,
    qry_sysuser40_vs_sysuser50.sysuser90_fecha,
    qry_sysuser40_vs_sysuser50.sysuser90_status,
    qry_sysuser40_vs_sysuser50.sysuser90_motivo,
    qry_sysuser40_vs_sysuser50.sysuser90_fapl,
    sysuser10_cab_movil.sysuser10_nombres,
    sysuser10_cab_movil.sysuser10_apellidos
    from qry_sysuser40_vs_sysuser50
    inner join sysuser11_det_contactos on (sysuser11_det_contactos.id_sysuser11 = qry_sysuser40_vs_sysuser50.rela_sysuser11)
    inner join sysuser10_cab_movil on (sysuser10_cab_movil.id_sysuser10 = sysuser11_det_contactos.rela_sysuser10)
    where sysuser11_det_contactos.rela_sysuser10_anfitrion = :rela_sysuser10_anfitrion
      and upper(trim(qry_sysuser40_vs_sysuser50.sysuser90_tipo)) = upper(trim(:tipo))
      and sysuser90_fecha >= :fecha_desde
      and sysuser90_fecha <= :fecha_hasta
    into :rela_sysuser10_alta,
         :id_sysuser90,
         :sysuser90_concepto,
         :sysuser90_cantidad,
         :sysuser90_importe,
         :sysuser90_total,
         :sysuser90_fecha,
         :sysuser90_status,
         :sysuser90_motivo,
         :sysuser90_fapl,
         :sysuser10_nombres,
         :sysuser10_apellidos
    do
    begin
        if (rela_sysuser10_alta = rela_sysuser10_anfitrion) then
            sysuser90_owner = 'Empresa';
        else
            sysuser90_owner = 'Cliente';

        if (trim(upper(tipo)) = 'PAGO' and sysuser90_status != 2) then
        begin
            sysuser90_importe = sysuser90_importe * (-1);
            sysuser90_total = sysuser90_total * (-1);
        end

        sysuser90_entidad = trim(:sysuser10_nombres) || ' ' || trim(:sysuser10_apellidos);

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE QRY_SYSUSER11 (
    STATUS INTEGER,
    RELA_SYSUSER10 BIGINT)
RETURNS (
    RELA_SYSUSER10_CLIENTE BIGINT,
    ID_SYSUSER11 BIGINT,
    SYSUSER10_INVITADO VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_TELEFONO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_CORREO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER12_STATUS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER12_STATUS_TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER12_CREDITO DOUBLE PRECISION,
    SYSUSER12_DISPONIBLE DOUBLE PRECISION,
    SYSUSER12_PAGOS FLOAT,
    SYSUSER12_COMPRAS DOUBLE PRECISION,
    SYSUSER12_BALANCE DOUBLE PRECISION,
    SYSUSER12_CORTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER12_CORTE_TIPO INTEGER,
    SYSUSER12_CORTE_SEMANA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER12_CORTE_DIA INTEGER,
    SYSUSER12_DIAS INTEGER,
    SYSUSER10_GEOLOC_ULT VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOVE_COMPRAS INTEGER,
    NOVE_PAGOS INTEGER,
    CON_CATALOGO INTEGER,
    SYSUSER11_FAPL TIMESTAMP)
AS
declare variable ID_SYSUSER12 bigint;
declare variable SYSUSER10_NOMBRES varchar(400);
declare variable SYSUSER10_APELLIDOS varchar(400);
declare variable FECHA_CORTE date;
begin
    select first 1 sysuser41_det_productos.id_sysuser41
    from sysuser41_det_productos
    where sysuser41_det_productos.rela_sysuser10 = :rela_sysuser10
    into :con_catalogo;

    con_catalogo = iif(con_catalogo is null, 0, 1);

    for select
    sysuser11_det_contactos.rela_sysuser10,
    sysuser11_det_contactos.id_sysuser11,
    invitado.sysuser10_nombres,
    TRIM(invitado.sysuser10_apellidos),
    TRIM(invitado.sysuser10_telefono),
    invitado.sysuser10_correo,
    invitado.sysuser10_uuid,
    invitado.sysuser10_geoloc_ult,
    sysuser11_det_contactos.sysuser11_fapl
    from sysuser11_det_contactos
    inner join sysuser10_cab_movil invitado on (sysuser11_det_contactos.rela_sysuser10 = invitado.id_sysuser10)
    where sysuser11_det_contactos.rela_sysuser10_anfitrion = :rela_sysuser10
    and sysuser11_det_contactos.sysuser11_status = :status
    order by sysuser11_det_contactos.id_sysuser11 desc
    into :rela_sysuser10_cliente,
         :id_sysuser11,
         :sysuser10_nombres,
         :sysuser10_apellidos,
         :sysuser10_telefono,
         :sysuser10_correo,
         :sysuser10_uuid,
         :sysuser10_geoloc_ult,
         :sysuser11_fapl
    do
    begin
        id_sysuser12 = null;
        sysuser10_invitado = trim(sysuser10_nombres) || ' ' || trim(sysuser10_apellidos);

        sysuser12_credito = 0.0;
        sysuser12_disponible = 0.0;
        sysuser12_pagos = 0.0;
        sysuser12_compras = 0.0;
        sysuser12_balance = 0.0;

        sysuser12_corte = 'Por definir';
        sysuser12_corte_tipo = 0;
        sysuser12_corte_semana = null;
        sysuser12_corte_dia = null;

        sysuser12_dias = 0;
        sysuser12_status = 'Pendiente';
        sysuser12_status_tipo = 'warning';

        if (status = 1 or status = 2)  then
        begin
            select
            sysuser12_dep_clientes.id_sysuser12,
            sysuser12_dep_clientes.sysuser12_credito,
            sysuser12_dep_clientes.sysuser12_corte_tipo,
            sysuser12_dep_clientes.sysuser12_corte_semana,
            sysuser12_dep_clientes.sysuser12_corte_dia
            from sysuser12_dep_clientes
            where sysuser12_dep_clientes.rela_sysuser11 = :id_sysuser11
            into :id_sysuser12,
                 :sysuser12_credito,
                 :sysuser12_corte_tipo,
                 :sysuser12_corte_semana,
                 :sysuser12_corte_dia;
    
            if (id_sysuser12 is not null) then
            begin
                Select
                qry_sysuser11_corte.corte,
                qry_sysuser11_corte.fecha_corte
                from qry_sysuser11_corte(:sysuser12_corte_tipo, :sysuser12_corte_semana, :sysuser12_corte_dia)
                into :sysuser12_corte,
                     :fecha_corte;
    
                select
                qry_sysuser11_saldos.sysuser12_credito,
                qry_sysuser11_saldos.sysuser12_disponible,
                qry_sysuser11_saldos.sysuser12_compras,
                qry_sysuser11_saldos.sysuser12_pagos,
                qry_sysuser11_saldos.sysuser12_balance
                from qry_sysuser11_saldos(:id_sysuser12, null, null)
                into :sysuser12_credito,
                     :sysuser12_disponible,
                     :sysuser12_compras,
                     :sysuser12_pagos,
                     :sysuser12_balance;

                sysuser12_dias = 0;
                sysuser12_status = 'Al dia';
                sysuser12_status_tipo = 'ok';

               if (sysuser12_balance > 0.0) then
                begin
                    select
                    qry_sysuser11_vencimiento.dias,
                    qry_sysuser11_vencimiento.sysuser12_status,
                    qry_sysuser11_vencimiento.sysuser12_status_tipo
                    from qry_sysuser11_vencimiento(:fecha_corte)
                    into :sysuser12_dias,
                         :sysuser12_status,
                         :sysuser12_status_tipo;

                    if (sysuser12_balance > sysuser12_credito) then
                    begin
                      sysuser12_status = 'Limite excedido';
                      sysuser12_status_tipo = 'danger';
                    end
                    else if (sysuser12_disponible <= 0 and sysuser12_balance > 0) then
                    begin
                      sysuser12_status = 'Sin disponible';
                      sysuser12_status_tipo = 'alert';
                    end
                end
            end

            if (status = 1) then
            begin
                nove_compras = null;
                nove_pagos = null;

                select count(sysuser40_det_compras.id_sysuser40)
                from sysuser40_det_compras
                where sysuser40_det_compras.rela_sysuser11 = :id_sysuser11
                and sysuser40_det_compras.sysuser40_status != 2
                into :nove_compras;

                select count(sysuser50_det_pagos.id_sysuser50)
                from sysuser50_det_pagos
                where sysuser50_det_pagos.rela_sysuser11 = :id_sysuser11
                and sysuser50_det_pagos.sysuser50_status = 0
                into :nove_pagos;

                if (nove_compras is null) then nove_compras = 0;
                if (nove_pagos is null) then nove_pagos = 0;
            end
        end

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE QRY_SYSUSER11_COBRANZA (
    STATUS INTEGER,
    RELA_SYSUSER10 BIGINT)
RETURNS (
    RELA_SYSUSER10_CLIENTE BIGINT,
    ID_SYSUSER11 BIGINT,
    SYSUSER10_INVITADO VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_TELEFONO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_CORREO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER12_STATUS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER12_STATUS_TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER12_CREDITO DOUBLE PRECISION,
    SYSUSER12_DISPONIBLE DOUBLE PRECISION,
    SYSUSER12_PAGOS FLOAT,
    SYSUSER12_COMPRAS DOUBLE PRECISION,
    SYSUSER12_BALANCE DOUBLE PRECISION,
    SYSUSER12_CORTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER12_CORTE_TIPO INTEGER,
    SYSUSER12_CORTE_SEMANA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER12_CORTE_DIA INTEGER,
    SYSUSER10_GEOLOC_ULT VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER12_DIAS INTEGER,
    SYSUSER11_FAPL TIMESTAMP)
AS
begin
    for select
    qry_sysuser11.rela_sysuser10_cliente,
    qry_sysuser11.id_sysuser11,
    qry_sysuser11.sysuser10_invitado,
    qry_sysuser11.sysuser10_uuid,
    qry_sysuser11.sysuser10_telefono,
    qry_sysuser11.sysuser10_correo,
    qry_sysuser11.sysuser12_status,
    qry_sysuser11.sysuser12_status_tipo,
    qry_sysuser11.sysuser12_credito,
    qry_sysuser11.sysuser12_disponible,
    qry_sysuser11.sysuser12_pagos,
    qry_sysuser11.sysuser12_compras,
    qry_sysuser11.sysuser12_balance,
    qry_sysuser11.sysuser12_corte,
    qry_sysuser11.sysuser12_corte_tipo,
    qry_sysuser11.sysuser12_corte_semana, 
    qry_sysuser11.sysuser12_corte_dia,
    qry_sysuser11.sysuser10_geoloc_ult,
    qry_sysuser11.sysuser12_dias,
    qry_sysuser11.sysuser11_fapl
    from qry_sysuser11(:status, :rela_sysuser10)
    where qry_sysuser11.sysuser12_status_tipo != 'ok'
    and qry_sysuser11.sysuser12_balance > 0.0
    order by qry_sysuser11.sysuser12_dias asc,
             qry_sysuser11.sysuser10_invitado asc
    into :rela_sysuser10_cliente,
         :id_sysuser11,
         :sysuser10_invitado,
         :sysuser10_uuid,
         :sysuser10_telefono,
         :sysuser10_correo,
         :sysuser12_status,
         :sysuser12_status_tipo,
         :sysuser12_credito,
         :sysuser12_disponible,
         :sysuser12_pagos,
         :sysuser12_compras,
         :sysuser12_balance,
         :sysuser12_corte,
         :sysuser12_corte_tipo,
         :sysuser12_corte_semana,
         :sysuser12_corte_dia,
         :sysuser10_geoloc_ult,
         :sysuser12_dias,
         :sysuser11_fapl
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE QRY_SYSUSER11_CORTE (
    TIPO INTEGER,
    SEMANA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DIA INTEGER)
RETURNS (
    CORTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FECHA_CORTE DATE,
    FECHA_CORTE_ANT DATE)
AS
declare variable FECHA_BASE date;
declare variable PRIMER_DIA_MES date;
declare variable ULTIMO_DIA_MES date;
declare variable DIA_ACTUAL integer;
declare variable DIA_SEMANA_ACTUAL integer;
declare variable DIA_SEMANA_CORTE integer;
declare variable LUNES_SEMANA_SIGUIENTE date;
begin
  FECHA_BASE = current_date;
  DIA_ACTUAL = extract(day from FECHA_BASE);

  PRIMER_DIA_MES = FECHA_BASE - (DIA_ACTUAL - 1);
  ULTIMO_DIA_MES = dateadd(-1 day to dateadd(1 month to PRIMER_DIA_MES));

  if (TIPO = 1) then
  begin
    if (DIA is null or DIA < 1 or DIA > 28) then
      DIA = 5;

    FECHA_CORTE = PRIMER_DIA_MES + (DIA - 1);

    if (FECHA_CORTE < FECHA_BASE) then
    begin
      PRIMER_DIA_MES = dateadd(1 month to PRIMER_DIA_MES);
      FECHA_CORTE = PRIMER_DIA_MES + (DIA - 1);
    end

    FECHA_CORTE_ANT = dateadd(-1 month to FECHA_CORTE);
  end

  else if (TIPO = 2) then
  begin
    if (DIA = 15) then
    begin
      FECHA_CORTE = PRIMER_DIA_MES + 14;

      if (FECHA_CORTE < FECHA_BASE) then
      begin
        PRIMER_DIA_MES = dateadd(1 month to PRIMER_DIA_MES);
        FECHA_CORTE = PRIMER_DIA_MES + 14;
      end

      FECHA_CORTE_ANT =
        dateadd(-1 day to (FECHA_CORTE - (extract(day from FECHA_CORTE) - 1)));
    end
    else
    begin
      FECHA_CORTE = ULTIMO_DIA_MES;

      if (FECHA_CORTE < FECHA_BASE) then
      begin
        PRIMER_DIA_MES = dateadd(1 month to PRIMER_DIA_MES);
        FECHA_CORTE = dateadd(-1 day to dateadd(1 month to PRIMER_DIA_MES));
      end

      FECHA_CORTE_ANT =
        (FECHA_CORTE - (extract(day from FECHA_CORTE) - 1)) + 14;
    end
  end

  else if (TIPO = 3) then
  begin
    if (upper(SEMANA) = 'LUNES') then DIA_SEMANA_CORTE = 1;
    else if (upper(SEMANA) = 'MARTES') then DIA_SEMANA_CORTE = 2;
    else if (upper(SEMANA) = 'MIERCOLES') then DIA_SEMANA_CORTE = 3;
    else if (upper(SEMANA) = 'JUEVES') then DIA_SEMANA_CORTE = 4;
    else if (upper(SEMANA) = 'VIERNES') then DIA_SEMANA_CORTE = 5;
    else DIA_SEMANA_CORTE = 1;

    DIA_SEMANA_ACTUAL = extract(weekday from FECHA_BASE);

    LUNES_SEMANA_SIGUIENTE =
      FECHA_BASE + (8 - DIA_SEMANA_ACTUAL);

    if (DIA_SEMANA_ACTUAL = 0) then
      LUNES_SEMANA_SIGUIENTE = FECHA_BASE + 1;

    FECHA_CORTE = LUNES_SEMANA_SIGUIENTE + (DIA_SEMANA_CORTE - 1);
    FECHA_CORTE_ANT = dateadd(-7 day to FECHA_CORTE);
  end

  else
  begin
    FECHA_CORTE = FECHA_BASE;
    FECHA_CORTE_ANT = FECHA_BASE;
  end

  CORTE =
    lpad(extract(day from FECHA_CORTE), 2, '0') || '/' ||
    lpad(extract(month from FECHA_CORTE), 2, '0') || '/' ||
    extract(year from FECHA_CORTE);

  suspend;
end^


CREATE OR ALTER PROCEDURE QRY_SYSUSER11_MI_RED (
    ID_SYSUSER11_RAIZ BIGINT)
RETURNS (
    NIVEL INTEGER,
    PATH VARCHAR(500) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SYSUSER11 BIGINT,
    RELA_SYSUSER10_PADRE BIGINT,
    RELA_SYSUSER10_HIJO BIGINT,
    SYSUSER11_STATUS INTEGER,
    SYSUSER10_NOMBRES VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_APELLIDOS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_CORREO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_TELEFONO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
  for
    with recursive red as (
      select
        0 as nivel,
        cast(lpad(cast(c.id_sysuser11 as varchar(20)), 5, '0') as varchar(500)) as path,
        c.id_sysuser11,
        c.rela_sysuser10_anfitrion as rela_sysuser10_padre,
        c.rela_sysuser10 as rela_sysuser10_hijo,
        c.sysuser11_status
      from sysuser11_det_contactos c
      where c.id_sysuser11 = :id_sysuser11_raiz

      union all

      select
        r.nivel + 1,
        cast(r.path || '.' || lpad(c.id_sysuser11, 5, '0') as varchar(500)) as path,
        c.id_sysuser11,
        c.rela_sysuser10_anfitrion,
        c.rela_sysuser10,
        c.sysuser11_status
      from sysuser11_det_contactos c
      join red r on c.rela_sysuser10_anfitrion = r.rela_sysuser10_hijo
      where r.nivel < 20
      and r.rela_sysuser10_padre <> r.rela_sysuser10_hijo
    )

    select
      nivel,
      path,
      id_sysuser11,
      rela_sysuser10_padre,
      rela_sysuser10_hijo,
      sysuser11_status
    from red
    order by path
    into
      :nivel,
      :path,
      :id_sysuser11,
      :rela_sysuser10_padre,
      :rela_sysuser10_hijo,
      :sysuser11_status
  do
  begin
      select
      u.sysuser10_nombres,
      trim(u.sysuser10_apellidos),
      trim(u.sysuser10_correo),
      trim(u.sysuser10_telefono)
    from sysuser10_cab_movil u
    where u.id_sysuser10 = :rela_sysuser10_hijo
    into
      :sysuser10_nombres,
      :sysuser10_apellidos,
      :sysuser10_correo,
      :sysuser10_telefono;

    suspend;
  end
end^


CREATE OR ALTER PROCEDURE QRY_SYSUSER11_SALDOS (
    RELA_SYSUSER12 BIGINT,
    FECHA_CORTE DATE,
    FECHA_CORTE_ANT DATE)
RETURNS (
    SYSUSER12_CREDITO DOUBLE PRECISION,
    SYSUSER12_DISPONIBLE DOUBLE PRECISION,
    SYSUSER12_COMPRAS DOUBLE PRECISION,
    SYSUSER12_PAGOS DOUBLE PRECISION,
    SYSUSER12_BALANCE DOUBLE PRECISION,
    SYSUSER12_DEUDOR DOUBLE PRECISION)
AS
declare variable RELA_SYSUSER11 bigint;
declare variable SYSUSER12_PLAN integer;
declare variable SYSUSER12_PORCENTAJE double precision;
declare variable PAGO_MINIMO double precision;
declare variable SYSUSER12_COMPRAS_ULT double precision;
declare variable SYSUSER12_PAGOS_ULT double precision;
begin
    select
        s12.rela_sysuser11,
        s12.sysuser12_credito,
        s12.sysuser12_plan,
        s12.sysuser12_porcentaje
    from sysuser12_dep_clientes s12
    where s12.id_sysuser12 = :rela_sysuser12
    into :rela_sysuser11,
         :sysuser12_credito,
         :sysuser12_plan,
         :sysuser12_porcentaje;

    if (sysuser12_credito is null) then sysuser12_credito = 0.0;

    select sum(c.sysuser40_cantidad * c.sysuser40_importe)
    from sysuser40_det_compras c
    where c.rela_sysuser11 = :rela_sysuser11
    into :sysuser12_compras;
        
    select sum(p.sysuser50_importe)
    from sysuser50_det_pagos p
    where p.rela_sysuser11 = :rela_sysuser11
    and p.sysuser50_status = 1
    into :sysuser12_pagos;
        
    if (sysuser12_compras is null) then sysuser12_compras = 0.0;
    if (sysuser12_pagos is null) then sysuser12_pagos = 0.0;
        
    sysuser12_deudor = 0.0;
    sysuser12_balance = sysuser12_compras - sysuser12_pagos;

    /* ============================================================================================================== */
    /* ============================================================================================================== */

    if (fecha_corte is not null and fecha_corte_ant is not null) then
    begin
        select sum(c.sysuser40_cantidad * c.sysuser40_importe)
        from sysuser40_det_compras c
        where c.rela_sysuser11 = :rela_sysuser11
          and c.sysuser40_fecha >= :fecha_corte_ant
          and c.sysuser40_fecha <= :fecha_corte
        into :sysuser12_compras_ult;

        select sum(p.sysuser50_importe)
        from sysuser50_det_pagos p
        where p.rela_sysuser11 = :rela_sysuser11
          and p.sysuser50_status = 1
          and p.sysuser50_fecha >= :fecha_corte_ant
          and p.sysuser50_fecha <= :fecha_corte
        into :sysuser12_pagos_ult;

        if (sysuser12_compras_ult is null) then sysuser12_compras_ult = 0.0;
        if (sysuser12_pagos_ult is null) then sysuser12_pagos_ult = 0.0;

        if (sysuser12_balance > 0) then
        begin
            if (sysuser12_pagos_ult = 0) then
                sysuser12_deudor = sysuser12_balance;
            else
            begin
                if (sysuser12_plan = 1) then
                begin
                    -- hizo por lo menos un pago libero algo de credito
                end
                else if (sysuser12_plan = 2) then
                begin
                    if (sysuser12_pagos_ult < sysuser12_balance) then
                        sysuser12_deudor = sysuser12_balance - sysuser12_pagos_ult;
                end
                else if (sysuser12_plan = 3) then
                begin
                    pago_minimo = sysuser12_balance * (sysuser12_porcentaje / 100.0);

                    if (sysuser12_pagos_ult < pago_minimo) then
                        sysuser12_deudor = pago_minimo - sysuser12_pagos_ult;
                end
            end
        end

        ---sysuser12_compras = sysuser12_compras_ult;
        ---sysuser12_pagos = sysuser12_pagos_ult;
    end

    /* ============================================================================================================== */
    /* ============================================================================================================== */

    if (sysuser12_balance < 0) then sysuser12_balance = 0.0;

    sysuser12_disponible = sysuser12_credito - sysuser12_balance;

    if (sysuser12_disponible < 0) then sysuser12_disponible = 0.0;
    if (sysuser12_disponible > sysuser12_credito) then
        sysuser12_disponible = sysuser12_credito;

    suspend;
end^


CREATE OR ALTER PROCEDURE QRY_SYSUSER11_SALDOS_ANFITRION (
    RELA_SYSUSER10_P BIGINT)
RETURNS (
    RELA_SYSUSER10 BIGINT,
    RELA_SYSUSER11 BIGINT,
    ID_SYSUSER12 BIGINT,
    SYSUSER12_CREDITO DOUBLE PRECISION,
    SYSUSER12_DISPONIBLE DOUBLE PRECISION,
    SYSUSER12_COMPRAS DOUBLE PRECISION,
    SYSUSER12_PAGOS DOUBLE PRECISION,
    SYSUSER12_BALANCE DOUBLE PRECISION,
    SYSUSER10_NOMBRES VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_APELLIDOS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_TELEFONO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER10_CORREO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER12_FAPL TIMESTAMP)
AS
declare variable SYSUSER12_CREDITO_SUM double precision;
declare variable SYSUSER12_DISPONIBLE_SUM double precision;
declare variable SYSUSER12_COMPRAS_SUM double precision;
declare variable SYSUSER12_PAGOS_SUM double precision;
declare variable SYSUSER12_BALANCE_SUM double precision;
begin
    id_sysuser12 = 1;
    sysuser12_credito = 0.0;
    sysuser12_disponible = 0.0;
    sysuser12_compras = 0.0;
    sysuser12_pagos = 0.0;
    sysuser12_balance = 0.0;
    sysuser12_fapl = current_timestamp;

    select first 1
    c.id_sysuser11,
    c.rela_sysuser10,
    c.sysuser10_nombres,
    c.sysuser10_apellidos,
    c.sysuser10_telefono,
    c.sysuser10_correo
    from QRY_SYSUSER10_SYSUSER11 c
    where c.rela_sysuser10_invitado = :rela_sysuser10_p
    and c.sysuser11_status = 1
    order by c.id_sysuser11 desc
    into :rela_sysuser11,
         :rela_sysuser10,
         :sysuser10_nombres,
         :sysuser10_apellidos,
         :sysuser10_telefono,
         :sysuser10_correo;

    for select
    sysuser12_dep_clientes.id_sysuser12,
    sysuser12_dep_clientes.sysuser12_fapl
    from sysuser11_det_contactos
    inner join sysuser12_dep_clientes on (sysuser12_dep_clientes.rela_sysuser11 = sysuser11_det_contactos.id_sysuser11)
    where sysuser11_det_contactos.rela_sysuser10_anfitrion = :rela_sysuser10_p
    and sysuser11_det_contactos.sysuser11_status = 1
    into :id_sysuser12,
         :sysuser12_fapl
    do
    begin
        select
        qry_sysuser11_saldos.sysuser12_credito,
        qry_sysuser11_saldos.sysuser12_disponible,
        qry_sysuser11_saldos.sysuser12_compras,
        qry_sysuser11_saldos.sysuser12_pagos,
        qry_sysuser11_saldos.sysuser12_balance
        from qry_sysuser11_saldos(:id_sysuser12, null, null)
        into :sysuser12_credito_sum,
             :sysuser12_disponible_sum,
             :sysuser12_compras_sum,
             :sysuser12_pagos_sum,
             :sysuser12_balance_sum;

        sysuser12_credito = sysuser12_credito + sysuser12_credito_sum;
        sysuser12_disponible = sysuser12_disponible + sysuser12_disponible_sum;
        sysuser12_compras = sysuser12_compras + sysuser12_compras_sum;
        sysuser12_pagos = sysuser12_pagos + sysuser12_pagos_sum;
        sysuser12_balance = sysuser12_balance + sysuser12_balance_sum;
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE QRY_SYSUSER11_SALDOS_INVITADO (
    RELA_SYSUSER10 BIGINT,
    RELA_SYSUSER10_ANFITRION BIGINT)
RETURNS (
    ID_SYSUSER12 BIGINT,
    SYSUSER12_CREDITO DOUBLE PRECISION,
    SYSUSER12_DISPONIBLE DOUBLE PRECISION,
    SYSUSER12_COMPRAS DOUBLE PRECISION,
    SYSUSER12_PAGOS DOUBLE PRECISION,
    SYSUSER12_BALANCE DOUBLE PRECISION,
    SYSUSER12_DEUDOR DOUBLE PRECISION,
    SYSUSER12_FAPL TIMESTAMP)
AS
declare variable SYSUSER12_CORTE_TIPO integer;
declare variable SYSUSER12_CORTE_SEMANA varchar(50);
declare variable SYSUSER12_CORTE_DIA integer;
declare variable FECHA_CORTE date;
declare variable FECHA_CORTE_ANT date;
begin
    id_sysuser12 = null;
    sysuser12_credito = 0.0;
    sysuser12_disponible = 0.0;
    sysuser12_compras = 0.0;
    sysuser12_pagos = 0.0;
    sysuser12_balance = 0.0;
    sysuser12_fapl = current_timestamp;

    select
    sysuser12_dep_clientes.id_sysuser12,
    sysuser12_dep_clientes.sysuser12_fapl,
    sysuser12_dep_clientes.sysuser12_corte_tipo,
    sysuser12_dep_clientes.sysuser12_corte_semana,
    sysuser12_dep_clientes.sysuser12_corte_dia
    from sysuser11_det_contactos
    inner join sysuser12_dep_clientes on (sysuser12_dep_clientes.rela_sysuser11 = sysuser11_det_contactos.id_sysuser11)
    where sysuser11_det_contactos.rela_sysuser10_anfitrion = :rela_sysuser10_anfitrion
    and sysuser11_det_contactos.rela_sysuser10 = :rela_sysuser10
    and sysuser11_det_contactos.sysuser11_status = 1
    into :id_sysuser12,
         :sysuser12_fapl,
         :sysuser12_corte_tipo,
         :sysuser12_corte_semana,
         :sysuser12_corte_dia;


    if (id_sysuser12 is not null) then
    begin
        Select
        qry_sysuser11_corte.fecha_corte,
        qry_sysuser11_corte.fecha_corte_ant
        from qry_sysuser11_corte(:sysuser12_corte_tipo, :sysuser12_corte_semana, :sysuser12_corte_dia)
        into :fecha_corte,
             :fecha_corte_ant;
    
        select
        qry_sysuser11_saldos.sysuser12_credito,
        qry_sysuser11_saldos.sysuser12_disponible,
        qry_sysuser11_saldos.sysuser12_compras,
        qry_sysuser11_saldos.sysuser12_pagos,
        qry_sysuser11_saldos.sysuser12_balance,
        qry_sysuser11_saldos.sysuser12_deudor
        from qry_sysuser11_saldos(:id_sysuser12, :fecha_corte, :fecha_corte_ant)
        into :sysuser12_credito,
             :sysuser12_disponible,
             :sysuser12_compras,
             :sysuser12_pagos,
             :sysuser12_balance,
             :sysuser12_deudor;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE QRY_SYSUSER11_VENCIMIENTO (
    FECHA_CORTE DATE)
RETURNS (
    DIAS INTEGER,
    SYSUSER12_STATUS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER12_STATUS_TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    --sysuser12_status = Al dia, Por vencer, Vence hoy, Vencido, Pendiente
    --sysuser12_status_tipo = ok, alert, warning, danger

    dias = datediff(day, current_date, fecha_corte);

    if (dias < 0) then
    begin
        sysuser12_status = 'Vencido';
        sysuser12_status_tipo = 'danger';
    end
    else if (dias = 0) then
    begin
        sysuser12_status = 'Vence hoy';
        sysuser12_status_tipo = 'alert';
    end
    else if (dias <= 10) then
    begin
        sysuser12_status = 'Por vencer';
        sysuser12_status_tipo = 'warning';
    end
    else
    begin
        sysuser12_status = 'Al dia';
        sysuser12_status_tipo = 'ok';
    end


    suspend;
end^


CREATE OR ALTER PROCEDURE QRY_SYSUSER12 (
    ID_SYSUSER11 BIGINT)
RETURNS (
    ID_SYSUSER12 BIGINT,
    SYSUSER12_PORCENTAJE DOUBLE PRECISION,
    SYSUSER12_PLAN INTEGER,
    SYSUSER12_CORTE_TIPO INTEGER,
    SYSUSER12_CORTE_SEMANA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER12_CORTE_DIA INTEGER,
    FECHA_CORTE DATE,
    DIAS_AL_VTO INTEGER,
    SYSUSER12_FAPL TIMESTAMP)
AS
begin
    select
    sysuser12_dep_clientes.id_sysuser12,
    sysuser12_dep_clientes.sysuser12_porcentaje,
    sysuser12_dep_clientes.sysuser12_plan,
    sysuser12_dep_clientes.sysuser12_corte_tipo,
    sysuser12_dep_clientes.sysuser12_corte_semana,
    sysuser12_dep_clientes.sysuser12_corte_dia,
    sysuser12_dep_clientes.sysuser12_fapl
    from sysuser12_dep_clientes
    where sysuser12_dep_clientes.rela_sysuser11 = :id_sysuser11
    into :id_sysuser12,
         :sysuser12_porcentaje,
         :sysuser12_plan,
         :sysuser12_corte_tipo,
         :sysuser12_corte_semana,
         :sysuser12_corte_dia,
         :sysuser12_fapl;

    if (id_sysuser12 is not null) then
    begin
        Select
        qry_sysuser11_corte.fecha_corte
        from qry_sysuser11_corte(:sysuser12_corte_tipo, :sysuser12_corte_semana, :sysuser12_corte_dia)
        into :fecha_corte;
    
        dias_al_vto = datediff(day, current_date, :fecha_corte);
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE QRY_SYSUSER41_CARRITO (
    RELA_SYSUSER10_P BIGINT)
RETURNS (
    RELA_SYSUSER10 BIGINT,
    ID_SYSUSER41 BIGINT,
    SYSUSER41_PRODUCTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER41_INVENTARIO DOUBLE PRECISION,
    SYSUSER41_IMPORTE DOUBLE PRECISION,
    SYSUSER41_STATUS INTEGER,
    SYSUSER41_IMAGE VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER41_EXISTENCIA DOUBLE PRECISION,
    SYSUSER41_FAPL TIMESTAMP)
AS
declare variable V_CATALOG_OWNER bigint;
BEGIN
    /*
     * Por defecto utiliza el catálogo propio del anfitrión directo
     * recibido desde Flutter en catalogOwnerId.
     */
    V_CATALOG_OWNER = :RELA_SYSUSER10_P;

    /*
     * Si tiene una entrada en SYSUSER44, toma el catálogo de su
     * anfitrión. Si no existe, conserva el propietario original.
     */
    SELECT COALESCE(
        (
            SELECT FIRST 1
                C.RELA_SYSUSER10_ANFITRION
            FROM SYSUSER44_CAB_CATALOGO C
            WHERE C.RELA_SYSUSER10 = :RELA_SYSUSER10_P
            ORDER BY C.ID_SYSUSER44 DESC
        ),
        :RELA_SYSUSER10_P
    )
    FROM RDB$DATABASE
    INTO :V_CATALOG_OWNER;

    FOR
        SELECT
            Q.RELA_SYSUSER10,
            Q.ID_SYSUSER41,
            Q.SYSUSER41_PRODUCTO,
            Q.SYSUSER41_INVENTARIO,
            Q.SYSUSER41_IMPORTE,
            Q.SYSUSER41_STATUS,
            Q.SYSUSER41_IMAGE,
            Q.SYSUSER41_EXISTENCIA,
            Q.SYSUSER41_FAPL
        FROM QRY_SYSUSER41 Q
        WHERE Q.RELA_SYSUSER10 = :V_CATALOG_OWNER
          AND Q.SYSUSER41_STATUS = 0
        ORDER BY Q.SYSUSER41_PRODUCTO
        INTO
            :RELA_SYSUSER10,
            :ID_SYSUSER41,
            :SYSUSER41_PRODUCTO,
            :SYSUSER41_INVENTARIO,
            :SYSUSER41_IMPORTE,
            :SYSUSER41_STATUS,
            :SYSUSER41_IMAGE,
            :SYSUSER41_EXISTENCIA,
            :SYSUSER41_FAPL
    DO
    BEGIN
        SUSPEND;
    END
END^


CREATE OR ALTER PROCEDURE SMX$DB_TABLE_FIND_ALIAS (
    ALIAS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SMXDATA01 BIGINT,
    TABLAS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable CAMPO_ID varchar(400);
begin
    id_smxdata01 = 0;
    campo_id = 'ID_' || upper(trim(alias));

    for Select
    SMX$DB_DICC_TABLAS_Y_CAMPOS.tablas
    from SMX$DB_DICC_TABLAS_Y_CAMPOS
    where ALIAS = :alias and CAMPOS = :campo_id and not SMX$DB_DICC_TABLAS_Y_CAMPOS.tablas LIKE '%REMOTO%'
    into :tablas
    do
    begin
        id_smxdata01 = id_smxdata01 + 1;
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE SMX$DB_UTIL_LOGS (
    CUSUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CTIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CTABLA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NULTID BIGINT)
AS
declare variable NEXISTE bigint;
begin
    INSERT INTO socsyst90_mov_logs
    (socsyst90_USUARIO,
    socsyst90_ACCION,
    SOCSYST90_TABLA,
    socsyst90_ULTID)
    VALUES(:CUSUARIO, :CTIPO, :CTABLA, :NULTID);

    SELECT count(*) FROM SOCSYST91_TBL_ULTIDS
    WHERE SOCSYST91_TBL_ULTIDS.SOCSYST91_USUARIO =:CUSUARIO
    AND SOCSYST91_TBL_ULTIDS.socsyst91_ulttbl = :CTABLA
    INTO :NEXISTE;

    if (NEXISTE =0) then
      begin
        INSERT INTO SOCSYST91_TBL_ULTIDS
        (SOCSYST91_USUARIO, SOCSYST91_ULTID, SOCSYST91_ULTTBL)
        VALUES(:CUSUARIO, :NULTID, :CTABLA);
      end
    else
      begin
        UPDATE SOCSYST91_TBL_ULTIDS
        SET SOCSYST91_ULTID = :NULTID,
            socsyst91_ulttbl = :CTABLA,
            SOCSYST91_FAPL = current_timestamp
        WHERE SOCSYST91_USUARIO=:CUSUARIO
        AND socsyst91_ulttbl = :CTABLA;
      end
end^


CREATE OR ALTER PROCEDURE SP_CREATE_TABLE_KERNEL_OBJECTS (
    P_TABLE_NAME VARCHAR(31) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    P_EXECUTE INTEGER)
RETURNS (
    ORDEN INTEGER,
    FASE VARCHAR(40) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    OBJETO VARCHAR(31) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ESTADO VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COMANDO_SQL VARCHAR(8191) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOTA VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable V_TABLE varchar(31);
declare variable V_ALIAS varchar(31);
declare variable V_ID_FIELD varchar(31);
declare variable V_EXISTS integer;
declare variable V_MAX_ID bigint;
declare variable V_FIELD varchar(31);
declare variable V_RELA_ALIAS varchar(31);
declare variable V_TARGET_TABLE varchar(31);
declare variable V_TARGET_ID varchar(31);
declare variable V_FK_NAME varchar(31);
declare variable V_SQL varchar(8191);
declare variable V_HAS_LOG_PROC integer;
BEGIN
  ORDEN = 0;
  V_TABLE = UPPER(TRIM(P_TABLE_NAME));

  IF (P_EXECUTE IS NULL) THEN
    P_EXECUTE = 0;

  IF (POSITION('_' IN V_TABLE) <= 1) THEN
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'ERROR';
    OBJETO = V_TABLE;
    ESTADO = 'ERROR';
    COMANDO_SQL = NULL;
    NOTA = 'La tabla debe tener alias antes del primer "_". Ej: SYSUSER11_DET_CONTACTOS.';
    SUSPEND;
    EXIT;
  END

  V_ALIAS = SUBSTRING(V_TABLE FROM 1 FOR POSITION('_' IN V_TABLE) - 1);
  V_ID_FIELD = 'ID_' || V_ALIAS;

  SELECT COUNT(*)
  FROM RDB$RELATIONS R
  WHERE R.RDB$RELATION_NAME = :V_TABLE
    AND R.RDB$VIEW_BLR IS NULL
  INTO :V_EXISTS;

  IF (V_EXISTS = 0) THEN
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'ERROR';
    OBJETO = V_TABLE;
    ESTADO = 'ERROR';
    COMANDO_SQL = NULL;
    NOTA = 'No existe tabla real con ese nombre.';
    SUSPEND;
    EXIT;
  END

  SELECT COUNT(*)
  FROM RDB$RELATION_FIELDS RF
  WHERE RF.RDB$RELATION_NAME = :V_TABLE
    AND RF.RDB$FIELD_NAME = :V_ID_FIELD
  INTO :V_EXISTS;

  IF (V_EXISTS = 0) THEN
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'ERROR';
    OBJETO = V_ID_FIELD;
    ESTADO = 'ERROR';
    COMANDO_SQL = NULL;
    NOTA = 'La tabla no tiene campo primary esperado ' || V_ID_FIELD || '.';
    SUSPEND;
    EXIT;
  END

  SELECT COUNT(*)
  FROM RDB$PROCEDURES P
  WHERE P.RDB$PROCEDURE_NAME = 'SMX$DB_UTIL_LOGS'
  INTO :V_HAS_LOG_PROC;

  /***************************************************************************
    1) Generator / sequence SID_ALIAS
  ***************************************************************************/
  SELECT COUNT(*)
  FROM RDB$GENERATORS G
  WHERE G.RDB$GENERATOR_NAME = ('SID_' || :V_ALIAS)
  INTO :V_EXISTS;

  V_SQL = 'CREATE GENERATOR SID_' || V_ALIAS;

  ORDEN = ORDEN + 1;
  FASE = 'GENERATOR';
  OBJETO = 'SID_' || V_ALIAS;
  COMANDO_SQL = V_SQL || ';';

  IF (V_EXISTS > 0) THEN
  BEGIN
    ESTADO = 'SKIP';
    NOTA = 'Ya existe generator.';
  END
  ELSE
  BEGIN
    IF (P_EXECUTE = 1) THEN
      EXECUTE STATEMENT :V_SQL;

    ESTADO = IIF(P_EXECUTE = 1, 'OK', 'PREVIEW');
    NOTA = 'Generator creado o listo para crear.';
  END
  SUSPEND;

  /***************************************************************************
    2) Ajustar generator a MAX(ID_ALIAS)
  ***************************************************************************/
  V_SQL = 'SELECT MAX(' || V_ID_FIELD || ') FROM ' || V_TABLE;
  EXECUTE STATEMENT :V_SQL INTO :V_MAX_ID;
  IF (V_MAX_ID IS NULL) THEN
    V_MAX_ID = 0;

  V_SQL = 'SET GENERATOR SID_' || V_ALIAS || ' TO ' || V_MAX_ID;

  ORDEN = ORDEN + 1;
  FASE = 'GENERATOR_SET';
  OBJETO = 'SID_' || V_ALIAS;
  COMANDO_SQL = V_SQL || ';';

  IF (P_EXECUTE = 1) THEN
    EXECUTE STATEMENT :V_SQL;

  ESTADO = IIF(P_EXECUTE = 1, 'OK', 'PREVIEW');
  NOTA = 'Generator ajustado al MAX(' || V_ID_FIELD || ') = ' || V_MAX_ID || '.';
  SUSPEND;

  /***************************************************************************
    3) Primary key PKY_ALIAS
  ***************************************************************************/
  SELECT COUNT(*)
  FROM RDB$RELATION_CONSTRAINTS RC
  WHERE RC.RDB$CONSTRAINT_NAME = ('PKY_' || :V_ALIAS)
  INTO :V_EXISTS;

  V_SQL = 'ALTER TABLE ' || V_TABLE ||
          ' ADD CONSTRAINT PKY_' || V_ALIAS ||
          ' PRIMARY KEY (' || V_ID_FIELD || ')';

  ORDEN = ORDEN + 1;
  FASE = 'PRIMARY_KEY';
  OBJETO = 'PKY_' || V_ALIAS;
  COMANDO_SQL = V_SQL || ';';

  IF (V_EXISTS > 0) THEN
  BEGIN
    ESTADO = 'SKIP';
    NOTA = 'Ya existe primary key con esa nomenclatura.';
  END
  ELSE
  BEGIN
    IF (P_EXECUTE = 1) THEN
      EXECUTE STATEMENT :V_SQL;

    ESTADO = IIF(P_EXECUTE = 1, 'OK', 'PREVIEW');
    NOTA = 'Primary key creada o lista para crear.';
  END
  SUSPEND;

  /***************************************************************************
    4) Trigger TID_ALIAS
  ***************************************************************************/
  SELECT COUNT(*)
  FROM RDB$TRIGGERS T
  WHERE T.RDB$TRIGGER_NAME = ('TID_' || :V_ALIAS)
  INTO :V_EXISTS;

  V_SQL =
    'CREATE OR ALTER TRIGGER TID_' || V_ALIAS || ' FOR ' || V_TABLE || ASCII_CHAR(13) ||
    'ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0' || ASCII_CHAR(13) ||
    'AS ' || ASCII_CHAR(13) || ASCII_CHAR(13) ||
    'DECLARE VARIABLE cTipo CHAR(1); ' || ASCII_CHAR(13) ||
    'DECLARE VARIABLE nID BIGINT; ' || ASCII_CHAR(13) || ASCII_CHAR(13) ||
    'BEGIN ' || ASCII_CHAR(13) ||
    '    IF (INSERTING) THEN ' || ASCII_CHAR(13) ||
    '    BEGIN ' || ASCII_CHAR(13) ||
    '        NEW.' || V_ID_FIELD || ' = GEN_ID(SID_' || V_ALIAS || ',1); ' || ASCII_CHAR(13) ||
    '        cTipo = ''A''; ' || ASCII_CHAR(13) ||
    '        nID = NEW.' || V_ID_FIELD || '; ' || ASCII_CHAR(13) ||
    '    END ' || ASCII_CHAR(13) ||
    '    ELSE IF (UPDATING) THEN ' || ASCII_CHAR(13) ||
    '    BEGIN ' || ASCII_CHAR(13) ||
    '        cTipo = ''M''; ' || ASCII_CHAR(13) ||
    '        nID = OLD.' || V_ID_FIELD || '; ' || ASCII_CHAR(13) ||
    '    END ' || ASCII_CHAR(13) ||
    '    ELSE ' || ASCII_CHAR(13) ||
    '    BEGIN ' || ASCII_CHAR(13) ||
    '        cTipo = ''B''; ' || ASCII_CHAR(13) ||
    '        nID = OLD.' || V_ID_FIELD || '; ' || ASCII_CHAR(13) ||
    '    END ' || ASCII_CHAR(13) || ASCII_CHAR(13);

  IF (V_HAS_LOG_PROC > 0) THEN
    V_SQL = V_SQL ||
      '    EXECUTE PROCEDURE smx$db_util_logs ' || ASCII_CHAR(13) ||
      '            CURRENT_USER, ' || ASCII_CHAR(13) ||
      '            :cTipo, ' || ASCII_CHAR(13) ||
      '            ''' || V_ALIAS || ''',' || ASCII_CHAR(13) ||
      '            :nID; ' || ASCII_CHAR(13);

  V_SQL = V_SQL || 'END';

  ORDEN = ORDEN + 1;
  FASE = 'TRIGGER';
  OBJETO = 'TID_' || V_ALIAS;
  COMANDO_SQL = V_SQL || ';';

  IF (V_EXISTS > 0) THEN
  BEGIN
    ESTADO = 'SKIP';
    NOTA = 'Ya existe trigger con esa nomenclatura.';
  END
  ELSE
  BEGIN
    IF (P_EXECUTE = 1) THEN
      EXECUTE STATEMENT :V_SQL;

    ESTADO = IIF(P_EXECUTE = 1, 'OK', 'PREVIEW');
    NOTA = 'Trigger creado o listo para crear.';
  END
  SUSPEND;

  /***************************************************************************
    5) Foreign keys por cada campo RELA_ALIASDESTINO
  ***************************************************************************/
  FOR
    SELECT TRIM(RF.RDB$FIELD_NAME)
    FROM RDB$RELATION_FIELDS RF
    WHERE RF.RDB$RELATION_NAME = :V_TABLE
      AND RF.RDB$FIELD_NAME STARTING WITH 'RELA_'
    ORDER BY RF.RDB$FIELD_POSITION
    INTO :V_FIELD
  DO
  BEGIN
    V_RELA_ALIAS = SUBSTRING(V_FIELD FROM 6 FOR 9);
    V_TARGET_ID = 'ID_' || V_RELA_ALIAS;
    V_TARGET_TABLE = NULL;

    SELECT FIRST 1 TRIM(R.RDB$RELATION_NAME)
    FROM RDB$RELATIONS R
    JOIN RDB$RELATION_FIELDS RFID
      ON RFID.RDB$RELATION_NAME = R.RDB$RELATION_NAME
     AND RFID.RDB$FIELD_NAME = :V_TARGET_ID
    WHERE R.RDB$VIEW_BLR IS NULL
      AND COALESCE(R.RDB$SYSTEM_FLAG, 0) = 0
      AND R.RDB$RELATION_NAME STARTING WITH (:V_RELA_ALIAS || '_')
    ORDER BY R.RDB$RELATION_NAME
    INTO :V_TARGET_TABLE;

    V_FK_NAME = SUBSTRING('FKY_' || V_ALIAS || '_' || SUBSTRING(V_FIELD FROM 6) FROM 1 FOR 31);
    IF (CHAR_LENGTH(V_FK_NAME) > 31) THEN
      V_FK_NAME = SUBSTRING(V_FK_NAME FROM 1 FOR 31);

    ORDEN = ORDEN + 1;
    FASE = 'FOREIGN_KEY';
    OBJETO = V_FK_NAME;

    IF (V_TARGET_TABLE IS NULL) THEN
    BEGIN
      ESTADO = 'WARN';
      COMANDO_SQL = NULL;
      NOTA = 'No se encontro tabla destino para ' || V_FIELD || ' -> alias ' || V_RELA_ALIAS || '.';
      SUSPEND;
    END
    ELSE
    BEGIN
      SELECT COUNT(*)
      FROM RDB$RELATION_CONSTRAINTS RC
      WHERE RC.RDB$CONSTRAINT_NAME = :V_FK_NAME
      INTO :V_EXISTS;

      V_SQL = 'ALTER TABLE ' || V_TABLE ||
              ' ADD CONSTRAINT ' || V_FK_NAME ||
              ' FOREIGN KEY (' || V_FIELD || ')' ||
              ' REFERENCES ' || V_TARGET_TABLE || ' (' || V_TARGET_ID || ')';

      COMANDO_SQL = V_SQL || ';';

      IF (V_EXISTS > 0) THEN
      BEGIN
        ESTADO = 'SKIP';
        NOTA = 'Ya existe foreign key con esa nomenclatura.';
      END
      ELSE
      BEGIN
        IF (P_EXECUTE = 1) THEN
          EXECUTE STATEMENT :V_SQL;

        ESTADO = IIF(P_EXECUTE = 1, 'OK', 'PREVIEW');
        NOTA = 'FK hacia ' || V_TARGET_TABLE || '.';
      END
      SUSPEND;
    END
  END
END^


CREATE OR ALTER PROCEDURE SP_DROP_BY_ALIAS (
    P_ALIAS VARCHAR(31) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    P_MAX_LEVEL INTEGER)
RETURNS (
    ORDEN INTEGER,
    FASE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NIVEL INTEGER,
    TIPO_OBJETO VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    OBJETO VARCHAR(255) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COMANDO_SQL VARCHAR(8191) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ESTADO VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SQL_CODE INTEGER,
    GDS_CODE INTEGER,
    NOTA VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable V_ORDEN integer;
declare variable V_FASE varchar(50);
declare variable V_NIVEL integer;
declare variable V_TIPO_OBJETO varchar(20);
declare variable V_OBJETO varchar(255);
declare variable V_COMANDO_SQL varchar(8191);
declare variable V_NOTA varchar(2000);
BEGIN
  FOR
    SELECT
      P.ORDEN,
      P.FASE,
      P.NIVEL,
      P.TIPO_OBJETO,
      P.OBJETO,
      P.COMANDO_SQL,
      P.NOTA
    FROM SP_PREVIEW_DROP_BY_ALIAS(:P_ALIAS, :P_MAX_LEVEL) P
    WHERE P.COMANDO_SQL IS NOT NULL
    ORDER BY P.ORDEN
    INTO
      :V_ORDEN,
      :V_FASE,
      :V_NIVEL,
      :V_TIPO_OBJETO,
      :V_OBJETO,
      :V_COMANDO_SQL,
      :V_NOTA
  DO
  BEGIN
    ORDEN = V_ORDEN;
    FASE = V_FASE;
    NIVEL = V_NIVEL;
    TIPO_OBJETO = V_TIPO_OBJETO;
    OBJETO = V_OBJETO;
    COMANDO_SQL = V_COMANDO_SQL;
    SQL_CODE = NULL;
    GDS_CODE = NULL;

    BEGIN
      EXECUTE STATEMENT :V_COMANDO_SQL;

      ESTADO = 'OK';
      NOTA = 'Ejecutado correctamente. Commit pendiente.';
      SUSPEND;

    WHEN ANY DO
      BEGIN
        ESTADO = 'ERROR';
        SQL_CODE = SQLCODE;
        GDS_CODE = GDSCODE;
        NOTA = 'Fallo este comando. El SP se detuvo aqui. Hacer ROLLBACK o corregir manualmente.';
        SUSPEND;
        EXIT;
      END
    END
  END
END^


CREATE OR ALTER PROCEDURE SP_LIKE_DROP_BY_ALIAS (
    P_LIKE VARCHAR(31) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    P_MAX_LEVEL INTEGER)
RETURNS (
    TARGET_ALIAS VARCHAR(31) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TARGET_TABLE VARCHAR(31) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TABLA_ORDEN INTEGER,
    ORDEN INTEGER,
    FASE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NIVEL INTEGER,
    TIPO_OBJETO VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    OBJETO VARCHAR(255) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COMANDO_SQL VARCHAR(8191) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ESTADO VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SQL_CODE INTEGER,
    GDS_CODE INTEGER,
    NOTA VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
DECLARE VARIABLE V_LIKE VARCHAR(31);
DECLARE VARIABLE V_ALIAS VARCHAR(31);
DECLARE VARIABLE V_TABLE VARCHAR(31);
DECLARE VARIABLE V_TABLE_ORDER INTEGER;
DECLARE VARIABLE V_ORDEN INTEGER;
DECLARE VARIABLE V_FASE VARCHAR(50);
DECLARE VARIABLE V_NIVEL INTEGER;
DECLARE VARIABLE V_TIPO_OBJETO VARCHAR(20);
DECLARE VARIABLE V_OBJETO VARCHAR(255);
DECLARE VARIABLE V_COMANDO_SQL VARCHAR(8191);
DECLARE VARIABLE V_ESTADO VARCHAR(20);
DECLARE VARIABLE V_SQL_CODE INTEGER;
DECLARE VARIABLE V_GDS_CODE INTEGER;
DECLARE VARIABLE V_NOTA VARCHAR(2000);
BEGIN
  DELETE FROM TMP_LIKE_DROP_BY_ALIAS;

  V_LIKE = UPPER(TRIM(P_LIKE));

  IF (P_MAX_LEVEL IS NULL OR P_MAX_LEVEL < 1) THEN
    P_MAX_LEVEL = 10;

  /* Si no trae comodin, se asume "empieza con". */
  IF (POSITION('%' IN V_LIKE) = 0 AND POSITION('_' IN V_LIKE) = 0) THEN
    V_LIKE = V_LIKE || '%';

  /***************************************************************************
    Snapshot de tablas candidatas.

    TARGET_ALIAS se toma como el prefijo antes del primer "_".
    Ejemplo:
      ADUCTAG02_DET_ANTICIPOS -> ADUCTAG02
  ***************************************************************************/
  INSERT INTO TMP_LIKE_DROP_BY_ALIAS (TARGET_ALIAS, TARGET_TABLE)
  SELECT
    SUBSTRING(TRIM(R.RDB$RELATION_NAME) FROM 1 FOR POSITION('_' IN TRIM(R.RDB$RELATION_NAME)) - 1),
    TRIM(R.RDB$RELATION_NAME)
  FROM RDB$RELATIONS R
  WHERE COALESCE(R.RDB$SYSTEM_FLAG, 0) = 0
    AND R.RDB$VIEW_BLR IS NULL
    AND UPPER(TRIM(R.RDB$RELATION_NAME)) LIKE :V_LIKE
    AND POSITION('_' IN TRIM(R.RDB$RELATION_NAME)) > 1
  ORDER BY R.RDB$RELATION_NAME;

  V_TABLE_ORDER = 0;

  FOR
    SELECT TARGET_ALIAS, TARGET_TABLE
    FROM TMP_LIKE_DROP_BY_ALIAS
    ORDER BY TARGET_TABLE
    INTO :V_ALIAS, :V_TABLE
  DO
  BEGIN
    V_TABLE_ORDER = V_TABLE_ORDER + 1;

    TARGET_ALIAS = V_ALIAS;
    TARGET_TABLE = V_TABLE;
    TABLA_ORDEN = V_TABLE_ORDER;
    ORDEN = 0;
    FASE = 'INFO_TARGET_TABLE';
    NIVEL = NULL;
    TIPO_OBJETO = 'TABLE';
    OBJETO = V_TABLE;
    COMANDO_SQL = NULL;
    ESTADO = 'INFO';
    SQL_CODE = NULL;
    GDS_CODE = NULL;
    NOTA = 'Iniciando borrado para alias ' || V_ALIAS || ', tabla ' || V_TABLE || '.';
    SUSPEND;

    FOR
      SELECT
        D.ORDEN,
        D.FASE,
        D.NIVEL,
        D.TIPO_OBJETO,
        D.OBJETO,
        D.COMANDO_SQL,
        D.ESTADO,
        D.SQL_CODE,
        D.GDS_CODE,
        D.NOTA
      FROM SP_DROP_BY_ALIAS(:V_ALIAS, :P_MAX_LEVEL) D
      INTO
        :V_ORDEN,
        :V_FASE,
        :V_NIVEL,
        :V_TIPO_OBJETO,
        :V_OBJETO,
        :V_COMANDO_SQL,
        :V_ESTADO,
        :V_SQL_CODE,
        :V_GDS_CODE,
        :V_NOTA
    DO
    BEGIN
      TARGET_ALIAS = V_ALIAS;
      TARGET_TABLE = V_TABLE;
      TABLA_ORDEN = V_TABLE_ORDER;
      ORDEN = V_ORDEN;
      FASE = V_FASE;
      NIVEL = V_NIVEL;
      TIPO_OBJETO = V_TIPO_OBJETO;
      OBJETO = V_OBJETO;
      COMANDO_SQL = V_COMANDO_SQL;
      ESTADO = V_ESTADO;
      SQL_CODE = V_SQL_CODE;
      GDS_CODE = V_GDS_CODE;
      NOTA = V_NOTA;
      SUSPEND;

      IF (V_ESTADO = 'ERROR') THEN
        EXIT;
    END
  END
END^


CREATE OR ALTER PROCEDURE SP_PREVIEW_DROP_BY_ALIAS (
    P_ALIAS VARCHAR(31) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    P_MAX_LEVEL INTEGER)
RETURNS (
    ORDEN INTEGER,
    FASE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NIVEL INTEGER,
    TIPO_OBJETO VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    OBJETO VARCHAR(255) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COMANDO_SQL VARCHAR(8191) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOTA VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
DECLARE VARIABLE V_ALIAS VARCHAR(31);
DECLARE VARIABLE V_TARGET_TABLE VARCHAR(31);
DECLARE VARIABLE V_COUNT INTEGER;
DECLARE VARIABLE V_LEVEL INTEGER;
DECLARE VARIABLE V_BEFORE INTEGER;
DECLARE VARIABLE V_AFTER INTEGER;
DECLARE VARIABLE V_NAME VARCHAR(255);
DECLARE VARIABLE V_TYPE VARCHAR(20);
DECLARE VARIABLE V_SQL VARCHAR(8191);
BEGIN
  DELETE FROM TMP_DROP_BY_ALIAS_DEP;

  V_ALIAS = UPPER(TRIM(P_ALIAS));
  IF (P_MAX_LEVEL IS NULL OR P_MAX_LEVEL < 1) THEN
    P_MAX_LEVEL = 10;

  ORDEN = 0;

  /***************************************************************************
    Resolver alias -> tabla real.
  ***************************************************************************/
  SELECT COUNT(*)
  FROM RDB$RELATIONS R
  WHERE COALESCE(R.RDB$SYSTEM_FLAG, 0) = 0
    AND R.RDB$VIEW_BLR IS NULL
    AND UPPER(TRIM(R.RDB$RELATION_NAME)) LIKE (:V_ALIAS || '\_%') ESCAPE '\'
  INTO :V_COUNT;

  IF (V_COUNT = 0) THEN
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'ERROR';
    NIVEL = NULL;
    TIPO_OBJETO = NULL;
    OBJETO = V_ALIAS;
    COMANDO_SQL = NULL;
    NOTA = 'No se encontro tabla real para el alias.';
    SUSPEND;
    EXIT;
  END

  IF (V_COUNT > 1) THEN
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'ERROR_ALIAS_AMBIGUO';
    NIVEL = NULL;
    TIPO_OBJETO = NULL;
    OBJETO = V_ALIAS;
    COMANDO_SQL = NULL;
    NOTA = 'El alias encontro mas de una tabla. Candidatos abajo.';
    SUSPEND;

    FOR
      SELECT TRIM(R.RDB$RELATION_NAME)
      FROM RDB$RELATIONS R
      WHERE COALESCE(R.RDB$SYSTEM_FLAG, 0) = 0
        AND R.RDB$VIEW_BLR IS NULL
        AND UPPER(TRIM(R.RDB$RELATION_NAME)) LIKE (:V_ALIAS || '\_%') ESCAPE '\'
      ORDER BY R.RDB$RELATION_NAME
      INTO :V_NAME
    DO
    BEGIN
      ORDEN = ORDEN + 1;
      FASE = 'CANDIDATO_TABLA';
      NIVEL = NULL;
      TIPO_OBJETO = 'TABLE';
      OBJETO = V_NAME;
      COMANDO_SQL = NULL;
      NOTA = 'Candidato para el alias.';
      SUSPEND;
    END

    EXIT;
  END

  SELECT FIRST 1 TRIM(R.RDB$RELATION_NAME)
  FROM RDB$RELATIONS R
  WHERE COALESCE(R.RDB$SYSTEM_FLAG, 0) = 0
    AND R.RDB$VIEW_BLR IS NULL
    AND UPPER(TRIM(R.RDB$RELATION_NAME)) LIKE (:V_ALIAS || '\_%') ESCAPE '\'
  ORDER BY R.RDB$RELATION_NAME
  INTO :V_TARGET_TABLE;

  ORDEN = ORDEN + 1;
  FASE = 'INFO_TABLA';
  NIVEL = NULL;
  TIPO_OBJETO = 'TABLE';
  OBJETO = V_TARGET_TABLE;
  COMANDO_SQL = NULL;
  NOTA = 'Alias ' || V_ALIAS || ' resuelto a tabla real.';
  SUSPEND;

  /***************************************************************************
    Mostrar triggers propios de la tabla como INFO.
  ***************************************************************************/
  FOR
    SELECT TRIM(T.RDB$TRIGGER_NAME)
    FROM RDB$TRIGGERS T
    WHERE T.RDB$RELATION_NAME = :V_TARGET_TABLE
      AND COALESCE(T.RDB$SYSTEM_FLAG, 0) = 0
    ORDER BY T.RDB$TRIGGER_NAME
    INTO :V_NAME
  DO
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'INFO_TRIGGER_PROPIO';
    NIVEL = NULL;
    TIPO_OBJETO = 'TRIGGER';
    OBJETO = V_NAME;
    COMANDO_SQL = NULL;
    NOTA = 'Trigger propio de la tabla. No se genera DROP porque DROP TABLE debe borrarlo automaticamente.';
    SUSPEND;
  END

  /***************************************************************************
    Nivel 1: objetos que usan directamente la tabla.
    Excluimos triggers propios de la tabla objetivo.
  ***************************************************************************/
  INSERT INTO TMP_DROP_BY_ALIAS_DEP (OBJ_NAME, OBJ_TYPE, NIVEL)
  SELECT DISTINCT
    D.RDB$DEPENDENT_NAME,
    CASE
      WHEN EXISTS (SELECT 1 FROM RDB$PROCEDURES P WHERE P.RDB$PROCEDURE_NAME = D.RDB$DEPENDENT_NAME) THEN 'PROCEDURE'
      WHEN EXISTS (SELECT 1 FROM RDB$RELATIONS R WHERE R.RDB$RELATION_NAME = D.RDB$DEPENDENT_NAME AND R.RDB$VIEW_BLR IS NOT NULL) THEN 'VIEW'
      ELSE 'TRIGGER'
    END,
    1
  FROM RDB$DEPENDENCIES D
  WHERE D.RDB$DEPENDED_ON_NAME = :V_TARGET_TABLE
    AND (
      EXISTS (SELECT 1 FROM RDB$PROCEDURES P WHERE P.RDB$PROCEDURE_NAME = D.RDB$DEPENDENT_NAME)
      OR EXISTS (SELECT 1 FROM RDB$RELATIONS R WHERE R.RDB$RELATION_NAME = D.RDB$DEPENDENT_NAME AND R.RDB$VIEW_BLR IS NOT NULL)
      OR EXISTS (
        SELECT 1
        FROM RDB$TRIGGERS T
        WHERE T.RDB$TRIGGER_NAME = D.RDB$DEPENDENT_NAME
          AND COALESCE(T.RDB$SYSTEM_FLAG, 0) = 0
      )
    )
    AND NOT EXISTS (
      SELECT 1
      FROM RDB$TRIGGERS TP
      WHERE TP.RDB$TRIGGER_NAME = D.RDB$DEPENDENT_NAME
        AND TP.RDB$RELATION_NAME = :V_TARGET_TABLE
    );

  /***************************************************************************
    Nivel 1 respaldo por texto de source.

    Motivo:
      En esta base RDB$DEPENDENCIES no siempre reporta todo. Ejemplo real:
      GRD_SICINGR85_WEB usaba ADUCTAG02_DET_ANTICIPOS en una subconsulta, pero
      no salia como VIEW dependiente en la salida del SP solo por metadata.

    Este bloque busca menciones de la tabla real dentro de:
      - RDB$VIEW_SOURCE
      - RDB$PROCEDURE_SOURCE
      - RDB$TRIGGER_SOURCE

    No es perfecto semanticamente, pero como el SP solo genera PREVIEW, es una
    capa de seguridad muy util.
  ***************************************************************************/

  INSERT INTO TMP_DROP_BY_ALIAS_DEP (OBJ_NAME, OBJ_TYPE, NIVEL)
  SELECT DISTINCT
    R.RDB$RELATION_NAME,
    'VIEW',
    1
  FROM RDB$RELATIONS R
  WHERE COALESCE(R.RDB$SYSTEM_FLAG, 0) = 0
    AND R.RDB$VIEW_BLR IS NOT NULL
    AND R.RDB$VIEW_SOURCE CONTAINING :V_TARGET_TABLE
    AND NOT EXISTS (
      SELECT 1
      FROM TMP_DROP_BY_ALIAS_DEP X
      WHERE X.OBJ_NAME = R.RDB$RELATION_NAME
    );

  INSERT INTO TMP_DROP_BY_ALIAS_DEP (OBJ_NAME, OBJ_TYPE, NIVEL)
  SELECT DISTINCT
    P.RDB$PROCEDURE_NAME,
    'PROCEDURE',
    1
  FROM RDB$PROCEDURES P
  WHERE P.RDB$PROCEDURE_SOURCE CONTAINING :V_TARGET_TABLE
    AND NOT EXISTS (
      SELECT 1
      FROM TMP_DROP_BY_ALIAS_DEP X
      WHERE X.OBJ_NAME = P.RDB$PROCEDURE_NAME
    );

  INSERT INTO TMP_DROP_BY_ALIAS_DEP (OBJ_NAME, OBJ_TYPE, NIVEL)
  SELECT DISTINCT
    T.RDB$TRIGGER_NAME,
    'TRIGGER',
    1
  FROM RDB$TRIGGERS T
  WHERE COALESCE(T.RDB$SYSTEM_FLAG, 0) = 0
    AND T.RDB$TRIGGER_SOURCE CONTAINING :V_TARGET_TABLE
    AND NOT EXISTS (
      SELECT 1
      FROM RDB$TRIGGERS TP
      WHERE TP.RDB$TRIGGER_NAME = T.RDB$TRIGGER_NAME
        AND TP.RDB$RELATION_NAME = :V_TARGET_TABLE
    )
    AND NOT EXISTS (
      SELECT 1
      FROM TMP_DROP_BY_ALIAS_DEP X
      WHERE X.OBJ_NAME = T.RDB$TRIGGER_NAME
    );

  /***************************************************************************
    Niveles 2..P_MAX_LEVEL:
    objetos que usan los objetos del nivel anterior.
  ***************************************************************************/
  V_LEVEL = 2;
  WHILE (V_LEVEL <= P_MAX_LEVEL) DO
  BEGIN
    SELECT COUNT(*) FROM TMP_DROP_BY_ALIAS_DEP INTO :V_BEFORE;

    INSERT INTO TMP_DROP_BY_ALIAS_DEP (OBJ_NAME, OBJ_TYPE, NIVEL)
    SELECT DISTINCT
      D.RDB$DEPENDENT_NAME,
      CASE
        WHEN EXISTS (SELECT 1 FROM RDB$PROCEDURES P WHERE P.RDB$PROCEDURE_NAME = D.RDB$DEPENDENT_NAME) THEN 'PROCEDURE'
        WHEN EXISTS (SELECT 1 FROM RDB$RELATIONS R WHERE R.RDB$RELATION_NAME = D.RDB$DEPENDENT_NAME AND R.RDB$VIEW_BLR IS NOT NULL) THEN 'VIEW'
        ELSE 'TRIGGER'
      END,
      :V_LEVEL
    FROM RDB$DEPENDENCIES D
    JOIN TMP_DROP_BY_ALIAS_DEP L
      ON D.RDB$DEPENDED_ON_NAME = L.OBJ_NAME
     AND L.NIVEL = (:V_LEVEL - 1)
    WHERE (
      EXISTS (SELECT 1 FROM RDB$PROCEDURES P WHERE P.RDB$PROCEDURE_NAME = D.RDB$DEPENDENT_NAME)
      OR EXISTS (SELECT 1 FROM RDB$RELATIONS R WHERE R.RDB$RELATION_NAME = D.RDB$DEPENDENT_NAME AND R.RDB$VIEW_BLR IS NOT NULL)
      OR EXISTS (
        SELECT 1
        FROM RDB$TRIGGERS T
        WHERE T.RDB$TRIGGER_NAME = D.RDB$DEPENDENT_NAME
          AND COALESCE(T.RDB$SYSTEM_FLAG, 0) = 0
      )
    )
    AND NOT EXISTS (
      SELECT 1
      FROM TMP_DROP_BY_ALIAS_DEP X
      WHERE X.OBJ_NAME = D.RDB$DEPENDENT_NAME
    );

    SELECT COUNT(*) FROM TMP_DROP_BY_ALIAS_DEP INTO :V_AFTER;

    IF (V_AFTER = V_BEFORE) THEN
      V_LEVEL = P_MAX_LEVEL + 1;
    ELSE
      V_LEVEL = V_LEVEL + 1;
  END

  /***************************************************************************
    Salida de cascada: niveles mas lejanos primero.
  ***************************************************************************/
  FOR
    SELECT
      D.NIVEL,
      D.OBJ_TYPE,
      TRIM(D.OBJ_NAME),
      CASE
        WHEN D.OBJ_TYPE = 'PROCEDURE' THEN 'DROP PROCEDURE ' || TRIM(D.OBJ_NAME) || ';'
        WHEN D.OBJ_TYPE = 'VIEW' THEN 'DROP VIEW ' || TRIM(D.OBJ_NAME) || ';'
        WHEN D.OBJ_TYPE = 'TRIGGER' THEN 'DROP TRIGGER ' || TRIM(D.OBJ_NAME) || ';'
        ELSE '/* Revisar manualmente: ' || TRIM(D.OBJ_NAME) || ' */'
      END
    FROM TMP_DROP_BY_ALIAS_DEP D
    ORDER BY D.NIVEL DESC, D.OBJ_TYPE, D.OBJ_NAME
    INTO :NIVEL, :V_TYPE, :V_NAME, :V_SQL
  DO
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'DROP_DEPENDIENTE';
    TIPO_OBJETO = V_TYPE;
    OBJETO = V_NAME;
    COMANDO_SQL = V_SQL;
    NOTA = 'Objeto que usa directa o indirectamente la tabla. Borrar consumidores primero.';
    SUSPEND;
  END

  /***************************************************************************
    FK entrantes: otras tablas apuntan a la tabla objetivo.
  ***************************************************************************/
  FOR
    SELECT
      'ALTER TABLE ' || TRIM(FK.RDB$RELATION_NAME) ||
      ' DROP CONSTRAINT ' || TRIM(FK.RDB$CONSTRAINT_NAME) || ';',
      TRIM(FK.RDB$RELATION_NAME) || '.' || TRIM(FK.RDB$CONSTRAINT_NAME)
    FROM RDB$RELATION_CONSTRAINTS PK
    JOIN RDB$REF_CONSTRAINTS RF
      ON RF.RDB$CONST_NAME_UQ = PK.RDB$CONSTRAINT_NAME
    JOIN RDB$RELATION_CONSTRAINTS FK
      ON FK.RDB$CONSTRAINT_NAME = RF.RDB$CONSTRAINT_NAME
    WHERE PK.RDB$RELATION_NAME = :V_TARGET_TABLE
      AND FK.RDB$CONSTRAINT_TYPE = 'FOREIGN KEY'
    ORDER BY FK.RDB$RELATION_NAME, FK.RDB$CONSTRAINT_NAME
    INTO :V_SQL, :V_NAME
  DO
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'DROP_FK_ENTRANTE';
    NIVEL = NULL;
    TIPO_OBJETO = 'CONSTRAINT';
    OBJETO = V_NAME;
    COMANDO_SQL = V_SQL;
    NOTA = 'FK de otra tabla hacia la tabla objetivo.';
    SUSPEND;
  END

  /***************************************************************************
    FK salientes: la tabla objetivo apunta a otras tablas.
  ***************************************************************************/
  FOR
    SELECT
      'ALTER TABLE ' || TRIM(RC.RDB$RELATION_NAME) ||
      ' DROP CONSTRAINT ' || TRIM(RC.RDB$CONSTRAINT_NAME) || ';',
      TRIM(RC.RDB$RELATION_NAME) || '.' || TRIM(RC.RDB$CONSTRAINT_NAME)
    FROM RDB$RELATION_CONSTRAINTS RC
    WHERE RC.RDB$RELATION_NAME = :V_TARGET_TABLE
      AND RC.RDB$CONSTRAINT_TYPE = 'FOREIGN KEY'
    ORDER BY RC.RDB$CONSTRAINT_NAME
    INTO :V_SQL, :V_NAME
  DO
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'DROP_FK_SALIENTE';
    NIVEL = NULL;
    TIPO_OBJETO = 'CONSTRAINT';
    OBJETO = V_NAME;
    COMANDO_SQL = V_SQL;
    NOTA = 'FK propia de la tabla objetivo hacia otra tabla.';
    SUSPEND;
  END

  /***************************************************************************
    Constraints propias no-FK: UNIQUE, CHECK, PRIMARY KEY.
  ***************************************************************************/
  FOR
    SELECT
      'ALTER TABLE ' || TRIM(RC.RDB$RELATION_NAME) ||
      ' DROP CONSTRAINT ' || TRIM(RC.RDB$CONSTRAINT_NAME) || ';',
      TRIM(RC.RDB$RELATION_NAME) || '.' || TRIM(RC.RDB$CONSTRAINT_NAME),
      TRIM(RC.RDB$CONSTRAINT_TYPE)
    FROM RDB$RELATION_CONSTRAINTS RC
    WHERE RC.RDB$RELATION_NAME = :V_TARGET_TABLE
      AND RC.RDB$CONSTRAINT_TYPE <> 'FOREIGN KEY'
    ORDER BY
      CASE RC.RDB$CONSTRAINT_TYPE
        WHEN 'CHECK' THEN 1
        WHEN 'UNIQUE' THEN 2
        WHEN 'PRIMARY KEY' THEN 3
        ELSE 9
      END,
      RC.RDB$CONSTRAINT_NAME
    INTO :V_SQL, :V_NAME, :V_TYPE
  DO
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'DROP_CONSTRAINT_PROPIA';
    NIVEL = NULL;
    TIPO_OBJETO = V_TYPE;
    OBJETO = V_NAME;
    COMANDO_SQL = V_SQL;
    NOTA = 'Constraint propia de la tabla objetivo.';
    SUSPEND;
  END

  /***************************************************************************
    DROP TABLE.
  ***************************************************************************/
  ORDEN = ORDEN + 1;
  FASE = 'DROP_TABLE';
  NIVEL = NULL;
  TIPO_OBJETO = 'TABLE';
  OBJETO = V_TARGET_TABLE;
  COMANDO_SQL = 'DROP TABLE ' || V_TARGET_TABLE || ';';
  NOTA = 'Al borrar la tabla se borran sus triggers propios.';
  SUSPEND;

  /***************************************************************************
    DROP GENERATOR al final.
  ***************************************************************************/
  SELECT COUNT(*)
  FROM RDB$GENERATORS G
  WHERE COALESCE(G.RDB$SYSTEM_FLAG, 0) = 0
    AND TRIM(G.RDB$GENERATOR_NAME) = ('SID_' || :V_ALIAS)
  INTO :V_COUNT;

  IF (V_COUNT > 0) THEN
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'DROP_GENERATOR';
    NIVEL = NULL;
    TIPO_OBJETO = 'GENERATOR';
    OBJETO = 'SID_' || V_ALIAS;
    COMANDO_SQL = 'DROP GENERATOR SID_' || V_ALIAS || ';';
    NOTA = 'Generator por convencion. Va al final, despues del DROP TABLE.';
    SUSPEND;
  END
  ELSE
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'INFO_GENERATOR';
    NIVEL = NULL;
    TIPO_OBJETO = 'GENERATOR';
    OBJETO = 'SID_' || V_ALIAS;
    COMANDO_SQL = NULL;
    NOTA = 'No existe generator exacto SID_' || V_ALIAS || '. Revisar manualmente si aplica.';
    SUSPEND;
  END
END^


CREATE OR ALTER PROCEDURE SP_SYSUSER99_SEGURIDAD_GET (
    P_RELA_SYSUSER10 BIGINT)
RETURNS (
    RELA_SYSUSER99 BIGINT,
    ID_SYSUSER10 BIGINT,
    SYSUSER99_USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER99_PASSWORD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EXISTE CHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ACCION VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOTA VARCHAR(300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable V_USUARIO varchar(50);
declare variable V_USUARIO_ONLY varchar(50);
declare variable V_PASSWORD varchar(50);
declare variable V_SQL varchar(1000);
declare variable V_EXISTE_SYSUSER10 bigint;
declare variable V_UUID varchar(50);
BEGIN
    ID_SYSUSER10 = :P_RELA_SYSUSER10;

    /* 1) Buscar si ya existe en SYSUSER99 */
    SELECT
        S.ID_SYSUSER99,
        S.SYSUSER99_USUARIO,
        S.SYSUSER99_PASSWORD
    FROM SYSUSER99_DEP_SEGURIDAD S
    WHERE S.RELA_SYSUSER10 = :P_RELA_SYSUSER10
    INTO
        :RELA_SYSUSER99,
        :SYSUSER99_USUARIO,
        :SYSUSER99_PASSWORD;

    IF (RELA_SYSUSER99 IS NOT NULL) THEN
    BEGIN
        EXISTE = 'S';
        ACCION = 'EXISTE';
        NOTA = 'Usuario ya existia en SYSUSER99.';
        SUSPEND;
        EXIT;
    END

    /* 2) Validar que exista el SYSUSER10 */
    SELECT U.ID_SYSUSER10
    FROM SYSUSER10_CAB_MOVIL U
    WHERE U.ID_SYSUSER10 = :P_RELA_SYSUSER10
    INTO :V_EXISTE_SYSUSER10;

    IF (V_EXISTE_SYSUSER10 IS NULL) THEN
    BEGIN
        EXISTE = 'N';
        ACCION = 'ERROR';
        NOTA = 'No existe ID_SYSUSER10 en SYSUSER10_CAB_MOVIL.';
        SUSPEND;
        EXIT;
    END

    /* 3) Construir usuario SMX$_000001 */
    V_USUARIO_ONLY = 'Z' || RIGHT('000000' || CAST(:P_RELA_SYSUSER10 AS VARCHAR(20)), 6);
    V_USUARIO = 'JAM$_' || V_USUARIO_ONLY;

    /* 4) Generar password */
    V_UUID = UUID_TO_CHAR(GEN_UUID());
    V_PASSWORD = 'SMX$' || SUBSTRING(REPLACE(:V_UUID, '-', '') FROM 1 FOR 12);

    /* 5) Crear usuario Firebird */
    BEGIN
        V_SQL = 'CREATE USER ' || V_USUARIO || ' PASSWORD ''' || V_PASSWORD || '''';
        EXECUTE STATEMENT :V_SQL
        AS USER 'SYSDBA' PASSWORD 'masterkey';
    WHEN ANY DO
        BEGIN
            /* Si ya existia en seguridad Firebird, le cambio clave */
            V_SQL = 'ALTER USER ' || V_USUARIO || ' PASSWORD ''' || V_PASSWORD || '''';
            EXECUTE STATEMENT :V_SQL
            AS USER 'SYSDBA' PASSWORD 'masterkey';
        END
    END

    /* 6) Dar rol */
    V_SQL = 'GRANT SMX_ROLE TO ' || V_USUARIO;
    EXECUTE STATEMENT :V_SQL
    AS USER 'SYSDBA' PASSWORD 'masterkey';

    /* 7) Guardar en SYSUSER99 */
    INSERT INTO SYSUSER99_DEP_SEGURIDAD (
        RELA_SYSUSER10,
        SYSUSER99_USUARIO,
        SYSUSER99_PASSWORD,
        SYSUSER99_ULT_ACCESO
    )
    VALUES (
        :P_RELA_SYSUSER10,
        :V_USUARIO_ONLY,
        :V_PASSWORD,
        CURRENT_TIMESTAMP
    )
    RETURNING ID_SYSUSER99
    INTO :RELA_SYSUSER99;

    SYSUSER99_USUARIO = :V_USUARIO_ONLY;
    SYSUSER99_PASSWORD = :V_PASSWORD;
    EXISTE = 'N';
    ACCION = 'CREADO';
    NOTA = 'Usuario Firebird creado/actualizado y registrado en SYSUSER99.';

    SUSPEND;
END^


CREATE OR ALTER PROCEDURE UPDATE_SYSUSER10_GEOLOCAL (
    ID_SYSUSER10 BIGINT,
    GEOLOCACION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ACCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_TMPUSER99 BIGINT,
    TMPUSER99_STATUS VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPUSER99_FAPL TIMESTAMP)
AS
begin
    update sysuser10_cab_movil set sysuser10_cab_movil.sysuser10_geoloc_ult = :geolocacion
    where sysuser10_cab_movil.id_sysuser10 = :id_sysuser10;

    id_tmpuser99 = 1;
    tmpuser99_status = 'OK';
    tmpuser99_fapl = current_timestamp;

    suspend;
end^


CREATE OR ALTER PROCEDURE UPDATE_SYSUSER40_SYSUSER50 (
    ACCION VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID BIGINT,
    STATUS INTEGER,
    MOTIVO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_TMPUSER99 BIGINT,
    TMPUSER99_STATUS VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPUSER99_FAPL TIMESTAMP)
AS
begin
    accion = upper(trim(accion));

    if(accion = 'C') then
    begin
        update sysuser40_det_compras set sysuser40_det_compras.sysuser40_status = :status
        where sysuser40_det_compras.id_sysuser40 = :id;
    end
    else if(accion = 'P') then
    begin
        update sysuser50_det_pagos set sysuser50_det_pagos.sysuser50_status = :status
        where sysuser50_det_pagos.id_sysuser50 = :id;
    end
    else if(accion = 'PR') then
    begin
        if (status <> 2 or trim(motivo) = '') then
        begin
            tmpuser99_status = 'ERROR';
            tmpuser99_fapl = current_timestamp;
            suspend;
            exit;
        end

        update sysuser50_det_pagos set
        sysuser50_det_pagos.sysuser50_status = :status,
        sysuser50_det_pagos.sysuser50_motivo = :motivo
        where sysuser50_det_pagos.id_sysuser50 = :id
        and sysuser50_det_pagos.sysuser50_status = 1;
    end

    id_tmpuser99 = 1;
    tmpuser99_status = 'OK';
    tmpuser99_fapl = current_timestamp;

    if (row_count = 0) then
    begin
        tmpuser99_status = 'ERROR';
        tmpuser99_fapl = current_timestamp;
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE UPDATE_SYSUSER90 (
    CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UUID_INVITADO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CORREO_INVITADO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SYSUSER90 BIGINT,
    SYSUSER90_ANFITRION_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER90_INVITADO_CORREO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER90_INVITADO_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER90_FAPL TIMESTAMP)
AS
begin
    uuid_invitado = trim(lower(uuid_invitado));
    correo_invitado = trim(lower(correo_invitado));

    SELECT
    SYSUSER90_TBL_SALDIFY.id_sysuser90,
    SYSUSER90_TBL_SALDIFY.sysuser90_anfitrion_uuid,
    SYSUSER90_TBL_SALDIFY.sysuser90_invitado_correo,
    SYSUSER90_TBL_SALDIFY.sysuser90_invitado_uuid,
    SYSUSER90_TBL_SALDIFY.sysuser90_fapl
    FROM SYSUSER90_TBL_SALDIFY
    WHERE SYSUSER90_CODIGO = :codigo
    INTO :id_sysuser90,
         :sysuser90_anfitrion_uuid,
         :sysuser90_invitado_correo,
         :sysuser90_invitado_uuid,
         :sysuser90_fapl;

    if (row_count = 0) then
        exit;

    if (
        trim(coalesce(sysuser90_invitado_correo, '')) = ''
        and trim(coalesce(sysuser90_invitado_uuid, '')) = ''
    ) then
    begin
        update sysuser90_tbl_saldify
        set
            sysuser90_invitado_correo = :correo_invitado,
            sysuser90_invitado_uuid = :uuid_invitado
        where id_sysuser90 = :id_sysuser90
          and trim(coalesce(sysuser90_invitado_correo, '')) = ''
          and trim(coalesce(sysuser90_invitado_uuid, '')) = '';

        if (row_count = 0) then
            exit;

        sysuser90_invitado_correo = :correo_invitado;
        sysuser90_invitado_uuid = :uuid_invitado;
    end

    suspend;
end^



SET TERM ; ^


